window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz135ocenka"]=[
["0","Преамбула и список изменений","","2026-08-04","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН (Особенности применения настоящего Федерального закона - Федеральный закон от 18.07.2009 № 181-ФЗ)\nОб оценочной деятельности в Российской Федерации\nПринят Государственной Думой 16 июля 1998 года\nОдобрен Советом Федерации 17 июля 1998 года\nСписок изменяющих документов(В редакции федеральных законов от 21.12.2001 № 178-ФЗ, от 21.03.2002 № 31-ФЗ, от 14.11.2002 № 143-ФЗ, от 10.01.2003 № 15-ФЗ, от 27.02.2003 № 29-ФЗ, от 22.08.2004 № 122-ФЗ, от 05.01.2006 № 7-ФЗ, от 27.07.2006 № 157-ФЗ, от 05.02.2007 № 13-ФЗ, от 13.07.2007 № 129-ФЗ, от 24.07.2007 № 220-ФЗ, от 30.06.2008 № 108-ФЗ, от 07.05.2009 № 91-ФЗ, от 17.07.2009 № 145-ФЗ, от 27.12.2009 № 343-ФЗ, от 27.12.2009 № 374-ФЗ, от 22.07.2010 № 167-ФЗ, от 28.12.2010 № 431-ФЗ, от 01.07.2011 № 169-ФЗ, от 11.07.2011 № 200-ФЗ, от 21.11.2011 № 327-ФЗ, от 30.11.2011 № 346-ФЗ, от 03.12.2011 № 383-ФЗ, от 07.06.2013 № 113-ФЗ, от 02.07.2013 № 185-ФЗ, от 23.07.2013 № 249-ФЗ, от 12.03.2014 № 33-ФЗ, от 04.06.2014 № 143-ФЗ, от 23.06.2014 № 171-ФЗ, от 21.07.2014 № 225-ФЗ, от 31.12.2014 № 499-ФЗ, от 08.03.2015 № 48-ФЗ, от 08.06.2015 № 145-ФЗ, от 13.07.2015 № 216-ФЗ, от 13.07.2015 № 224-ФЗ, от 29.12.2015 № 391-ФЗ, от 26.04.2016 № 111-ФЗ, от 02.06.2016 № 172-ФЗ, от 23.06.2016 № 221-ФЗ, от 03.07.2016 № 360-ФЗ, от 03.07.2016 № 361-ФЗ, от 29.07.2017 № 274-ФЗ, от 03.08.2018 № 312-ФЗ, от 28.11.2018 № 451-ФЗ, от 18.03.2020 № 66-ФЗ, от 31.07.2020 № 269-ФЗ, от 11.06.2021 № 170-ФЗ, от 02.07.2021 № 351-ФЗ, от 19.12.2022 № 546-ФЗ, от 13.06.2023 № 228-ФЗ, от 14.02.2024 № 17-ФЗ, от 31.07.2025 № 304-ФЗ, от 04.07.2026 № 240-ФЗ, от 04.08.2026 № 278-ФЗ)\n(С учетом федеральных законов от 18.07.2009 № 181-ФЗ, от 28.07.2012 № 144-ФЗ; Постановления Конституционного Суда Российской Федерации от 05.07.2016 № 15-П)"],
["1","Законодательство, регулирующее оценочную деятельность в Российской Федерации","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2006-07-27","Статья 1. Законодательство, регулирующее оценочную деятельность в Российской Федерации\nОценочная деятельность осуществляется в соответствии с международными договорами Российской Федерации, настоящим Федеральным законом, а также другими федеральными законами и иными нормативными правовыми актами Российской Федерации, регулирующими отношения, возникающие при осуществлении оценочной деятельности.\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["2","Отношения, регулируемые настоящим Федеральным законом","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2002-11-14","Статья 2. Отношения, регулируемые настоящим Федеральным законом\nНастоящий Федеральный закон определяет правовые основы регулирования оценочной деятельности в отношении объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, физическим лицам и юридическим лицам, для целей совершения сделок с объектами оценки, а также для иных целей. (В редакции Федерального закона от 14.11.2002 № 143-ФЗ)"],
["3","Понятие оценочной деятельности","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2016-07-03","Статья 3. Понятие оценочной деятельности\nДля целей настоящего Федерального закона под оценочной деятельностью понимается профессиональная деятельность субъектов оценочной деятельности, направленная на установление в отношении объектов оценки рыночной, кадастровой, ликвидационной, инвестиционной или иной предусмотренной федеральными стандартами оценки стоимости. (В редакции федеральных законов от 27.07.2006 № 157-ФЗ; от 22.07.2010 № 167-ФЗ; от 03.07.2016 № 360-ФЗ)\nДля целей настоящего Федерального закона под рыночной стоимостью объекта оценки понимается наиболее вероятная цена, по которой данный объект оценки может быть отчужден на открытом рынке в условиях конкуренции, когда стороны сделки действуют разумно, располагая всей необходимой информацией, а на величине цены сделки не отражаются какие-либо чрезвычайные обстоятельства, то есть когда:\nодна из сторон сделки не обязана отчуждать объект оценки, а другая сторона не обязана принимать исполнение;\nстороны сделки хорошо осведомлены о предмете сделки и действуют в своих интересах;\nобъект оценки представлен на открытом рынке посредством публичной оферты, типичной для аналогичных объектов оценки; (В редакции Федерального закона от 14.11.2002 № 143-ФЗ)\nцена сделки представляет собой разумное вознаграждение за объект оценки и принуждения к совершению сделки в отношении сторон сделки с чьей-либо стороны не было;\nплатеж за объект оценки выражен в денежной форме.\nПод кадастровой стоимостью понимается стоимость, установленная в результате проведения государственной кадастровой оценки или в результате рассмотрения споров о результатах определения кадастровой стоимости либо определенная в случаях, предусмотренных статьей 24.19 настоящего Федерального закона. (Дополнение частью - Федеральный закон от 22.07.2010 № 167-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nДля целей настоящего Федерального закона под ликвидационной стоимостью понимается расчетная величина, отражающая наиболее вероятную цену, по которой данный объект оценки может быть отчужден за срок экспозиции объекта оценки, меньший типичного срока экспозиции объекта оценки для рыночных условий, в условиях, когда продавец вынужден совершить сделку по отчуждению имущества. (Дополнение частью - Федеральный закон от 03.07.2016 № 360-ФЗ)\nДля целей настоящего Федерального закона под инвестиционной стоимостью понимается стоимость объекта оценки для конкретного лица или группы лиц при установленных данным лицом (лицами) инвестиционных целях использования объекта оценки. (Дополнение частью - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["4","Субъекты оценочной деятельности","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2016-06-02","Статья 4. Субъекты оценочной деятельности\nСубъектами оценочной деятельности признаются физические лица, являющиеся членами одной из саморегулируемых организаций оценщиков и застраховавшие свою ответственность в соответствии с требованиями настоящего Федерального закона (далее - оценщики).\nОценщик может осуществлять оценочную деятельность самостоятельно, занимаясь частной практикой, а также на основании трудового договора между оценщиком и юридическим лицом, которое соответствует условиям, установленным статьей 15.1 настоящего Федерального закона.\nОценщик может осуществлять оценочную деятельность по направлениям, указанным в квалификационном аттестате. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["5","Объекты оценки","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","","Статья 5. Объекты оценки\nК объектам оценки относятся:\nотдельные материальные объекты (вещи);\nсовокупность вещей, составляющих имущество лица, в том числе имущество определенного вида (движимое или недвижимое, в том числе предприятия);\nправо собственности и иные вещные права на имущество или отдельные вещи из состава имущества;\nправа требования, обязательства (долги);\nработы, услуги, информация;\nиные объекты гражданских прав, в отношении которых законодательством Российской Федерации установлена возможность их участия в гражданском обороте."],
["6","Право Российской Федерации, субъектов Российской Федерации или муниципальных образований, физических лиц и юридических лиц на проведение оценки принадлежащих им объектов оценки","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","","Статья 6. Право Российской Федерации, субъектов Российской Федерации или муниципальных образований, физических лиц и юридических лиц на проведение оценки принадлежащих им объектов оценки\nРоссийская Федерация, субъекты Российской Федерации или муниципальные образования, физические лица и юридические лица имеют право на проведение оценщиком оценки любых принадлежащих им объектов оценки на основаниях и условиях, предусмотренных настоящим Федеральным законом.\nПраво на проведение оценки объекта оценки является безусловным и не зависит от установленного законодательством Российской Федерации порядка осуществления государственного статистического учета и бухгалтерского учета и отчетности. Данное право распространяется и на проведение повторной оценки объекта оценки. Результаты проведения оценки объекта оценки могут быть использованы для корректировки данных бухгалтерского учета и отчетности.\nРезультаты проведения оценки объекта оценки могут быть обжалованы заинтересованными лицами в порядке, установленном законодательством Российской Федерации."],
["7","Предположение об установлении рыночной стоимости объекта оценки","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","","Статья 7. Предположение об установлении рыночной стоимости объекта оценки\nВ случае, если в нормативном правовом акте, содержащем требование обязательного проведения оценки какого-либо объекта оценки, либо в договоре об оценке объекта оценки (далее - договор) не определен конкретный вид стоимости объекта оценки, установлению подлежит рыночная стоимость данного объекта.\nУказанное правило подлежит применению и в случае использования в нормативном правовом акте не предусмотренных настоящим Федеральным законом или стандартами оценки терминов, определяющих вид стоимости объекта оценки, в том числе терминов \"действительная стоимость\", \"разумная стоимость\", \"эквивалентная стоимость\", \"реальная стоимость\" и других."],
["8","Обязательность проведения оценки объектов оценки","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2026-07-04","Статья 8. Обязательность проведения оценки объектов оценки\nПроведение оценки объекта оценки, принадлежащего полностью или частично Российской Федерации, субъекту Российской Федерации либо муниципальному образованию, в целях определения его стоимости (начальной цены) является обязательным для совершения сделок с таким объектом оценки, в том числе: (В редакции Федерального закона от 04.07.2026 № 240-ФЗ)\nпри определении стоимости объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, в целях их приватизации, передачи в доверительное управление либо передачи в аренду;\nпри использовании объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации либо муниципальным образованиям, в качестве предмета залога;\nпри продаже или ином отчуждении объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям;\nпри переуступке долговых обязательств, связанных с объектами оценки, принадлежащими Российской Федерации, субъектам Российской Федерации или муниципальным образованиям;\nпри передаче объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, в качестве вклада в уставные капиталы, фонды юридических лиц, а также при возникновении спора о стоимости объекта оценки, в том числе:\nпри национализации имущества;\nпри ипотечном кредитовании физических лиц и юридических лиц в случаях возникновения споров о величине стоимости предмета ипотеки;\nпри составлении брачных контрактов и разделе имущества разводящихся супругов по требованию одной из сторон или обеих сторон в случае возникновения спора о стоимости этого имущества;\nпри изъятии имущества для государственных или муниципальных нужд; (В редакции Федерального закона от 31.12.2014 № 499-ФЗ)\nпри проведении оценки объектов оценки в целях контроля за правильностью уплаты налогов в случае возникновения спора об исчислении налогооблагаемой базы.\nДействие настоящей статьи не распространяется на отношения, возникающие:\nпри распоряжении государственными и муниципальными унитарными предприятиями, государственными и муниципальными учреждениями имуществом, закрепленным за ними в хозяйственном ведении или оперативном управлении, за исключением случаев, если распоряжение имуществом в соответствии с законодательством Российской Федерации допускается с согласия собственника этого имущества;\nв случае распоряжения государственным или муниципальным имуществом при реорганизации государственных и муниципальных унитарных предприятий, государственных и муниципальных учреждений;\nв случаях, установленных Федеральным законом от 27 февраля 2003 года № 29-ФЗ \"Об особенностях управления и распоряжения имуществом железнодорожного транспорта\", Федеральным законом от 5 февраля 2007 года № 13-ФЗ \"Об особенностях управления и распоряжения имуществом и акциями организаций, осуществляющих деятельность в области использования атомной энергии, и о внесении изменений в отдельные законодательные акты Российской Федерации\" и Федеральным законом \"О Государственной корпорации по космической деятельности \"Роскосмос\"; (В редакции Федерального закона от 13.07.2015 № 216-ФЗ)\nв связи с передачей находящихся в федеральной собственности земельных участков, в том числе с расположенными на них и находящимися в федеральной собственности объектами недвижимого имущества, и находящегося в федеральной собственности другого имущества, и в отношении которых единый институт развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства, созданию объектов туристской инфраструктуры и иному развитию территорий\" выполняет функции агента Российской Федерации; (В редакции федеральных законов от 27.12.2009 № 343-ФЗ, от 08.03.2015 № 48-ФЗ, от 23.06.2016 № 221-ФЗ, от 14.02.2024 № 17-ФЗ)\nв связи с передачей находящихся в федеральной собственности автомобильных дорог общего пользования федерального значения и земельных участков Государственной компании \"Российские автомобильные дороги\" в соответствии с Федеральным законом \"О Государственной компании \"Российские автомобильные дороги\" и о внесении изменений в отдельные законодательные акты Российской Федерации\";\nв случае передачи в аренду находящегося в федеральной собственности аэродрома; (Дополнение абзацем - Федеральный закон от 26.04.2016 № 111-ФЗ)\nв отношении находящегося в федеральной собственности недвижимого имущества аэропортов Московского авиационного узла при реализации концессионных соглашений, объектами которых являются объекты производственной и инженерной инфраструктур аэропортов, аэродромы или здания и (или) сооружения, предназначенные для взлета, посадки, руления и стоянки воздушных судов, а также создаваемые и предназначенные для организации полетов гражданских воздушных судов инфраструктура воздушного транспорта и средства обслуживания воздушного движения, навигации, посадки и связи; (Дополнение абзацем - Федеральный закон от 26.04.2016 № 111-ФЗ) (В редакции Федерального закона от 03.08.2018 № 312-ФЗ)\nв случае передачи имущества, принадлежащего Российской Федерации, субъектам Российской Федерации либо муниципальным образованиям, в безвозмездное пользование органам власти Российской Федерации, субъектов Российской Федерации либо муниципальных образований, государственным, муниципальным унитарным предприятиям или государственным, муниципальным учреждениям; (Дополнение абзацем - Федеральный закон от 02.06.2016 № 172-ФЗ)\nв случае передачи имущества органам публичной власти федеральной территории \"Сириус\" в соответствии с положениями Федерального закона \"О федеральной территории \"Сириус\". (Дополнение абзацем - Федеральный закон от 02.07.2021 № 351-ФЗ)\n(Часть в редакции Федерального закона от 17.07.2009 № 145-ФЗ)\nВ отношении государственного или муниципального имущества, передаваемого по концессионному соглашению концедентом концессионеру или по соглашению о государственно-частном партнерстве, соглашению о муниципально-частном партнерстве публичным партнером частному партнеру, установление рыночной стоимости такого имущества не является обязательным, если иное не установлено федеральным законом. (Дополнение частью - Федеральный закон от 30.06.2008 № 108-ФЗ) (В редакции Федерального закона от 13.07.2015 № 224-ФЗ)\nЕсли цена государственного или муниципального имущества либо размер арендной платы за него установлены в соответствии с другими федеральными законами в связи с продажей, передачей в аренду или обременением сервитутом, рыночная стоимость данного имущества в соответствии с настоящим Федеральным законом не устанавливается. (Дополнение частью - Федеральный закон от 23.06.2014 № 171-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ) (Утратила силу - Федеральный закон от 29.12.2015 № 391-ФЗ)\n(Особенности применения статьи 8 - Федеральный закон от 29.12.2015 № 391-ФЗ)"],
["8.1","Информационная открытость процедуры оценки","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2021-07-02","Статья 8.1. Информационная открытость процедуры оценки\nВ целях обеспечения информационной открытости процедуры оценки объектов оценки в случаях проведения оценки, предусмотренных Федеральным законом от 26 декабря 1995 года № 208-ФЗ \"Об акционерных обществах\", Федеральным законом от 30 декабря 1995 года № 225-ФЗ \"О соглашениях о разделе продукции\", Федеральным законом от 8 мая 1996 года № 41-ФЗ \"О производственных кооперативах\", Федеральным законом от 8 февраля 1998 года № 14-ФЗ \"Об обществах с ограниченной ответственностью\", Федеральным законом от 7 мая 1998 года № 75-ФЗ \"О негосударственных пенсионных фондах\", Федеральным законом от 9 июля 1999 года № 160-ФЗ \"Об иностранных инвестициях в Российской Федерации\", Федеральным законом от 29 ноября 2001 года № 156-ФЗ \"Об инвестиционных фондах\", заказчик обязан включать информацию об отчете об оценке объекта оценки в Единый федеральный реестр сведений о фактах деятельности юридических лиц в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности, в течение десяти рабочих дней с даты принятия отчета об оценке объекта оценки. В Единый федеральный реестр сведений о фактах деятельности юридических лиц подлежат включению дата составления и порядковый номер отчета об оценке объекта оценки, основание для проведения оценщиком оценки объекта оценки, сведения об оценщике (фамилия, имя и (при наличии) отчество), идентифицирующие оценщика данные (страховой номер индивидуального лицевого счета оценщика в системе обязательного пенсионного страхования, идентификационный номер налогоплательщика (при наличии такого номера), сведения о членстве оценщика в саморегулируемой организации оценщиков, точное описание объекта оценки в соответствии с отчетом об оценке объекта оценки, дата определения стоимости объекта оценки, определенная оценщиком рыночная стоимость объекта оценки, информация об экспертном заключении на отчет об оценке объекта оценки (дата составления, порядковый номер, сведения об эксперте или экспертах (фамилия, имя и (при наличии) отчество), идентифицирующие эксперта данные (страховой номер индивидуального лицевого счета оценщика в системе обязательного пенсионного страхования, идентификационный номер налогоплательщика (при наличии такого номера), сведения о членстве эксперта или экспертов в саморегулируемой организации оценщиков, результаты экспертизы, а в отношении объекта оценки, принадлежащего юридическому лицу, реквизиты юридического лица и балансовая стоимость данного объекта оценки, иные сведения, предусмотренные федеральным законом или федеральными стандартами оценки.\nЗаказчик наряду с информацией, предусмотренной настоящей статьей, обязан включать отчет об оценке объекта оценки в Единый федеральный реестр сведений о фактах деятельности юридических лиц в течение десяти рабочих дней с даты его принятия при проведении оценки объектов оценки в следующих случаях:\nопределение стоимости объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, их продажа, приватизация, передача в качестве вклада в уставные капиталы, фонды юридических лиц или иное отчуждение, а также передача указанных объектов в доверительное управление либо в аренду;\nиспользование объектов оценки, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, в качестве предмета залога;\nпереуступка долговых обязательств, связанных с объектами оценки, принадлежащими Российской Федерации, субъектам Российской Федерации или муниципальным образованиям;\nизъятие имущества для государственных или муниципальных нужд (за исключением случаев, если заказчиком является физическое лицо).\nВ случае, если заказчиком является федеральный орган исполнительной власти, орган государственной власти субъекта Российской Федерации, орган публичной власти федеральной территории или орган местного самоуправления, включение информации об отчете об оценке объекта оценки и отчетов об оценке объектов оценки в Единый федеральный реестр сведений о фактах деятельности юридических лиц осуществляется без взимания платы. (В редакции Федерального закона от 02.07.2021 № 351-ФЗ)\nИнформация об отчете объекта оценки и указанный отчет, содержащие сведения, составляющие государственную тайну, опубликовываются в части, не содержащей сведения, составляющие государственную тайну.\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 391-ФЗ)\n(Особенности применения статьи 8.1 - Федеральный закон от 29.12.2015 № 391-ФЗ)"],
["9","Основания для проведения оценки объекта оценки","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2006-07-27","Статья 9. Основания для проведения оценки объекта оценки\nОснованием для проведения оценки является договор на проведение оценки указанных в статье 5 настоящего Федерального закона объектов, заключенный заказчиком с оценщиком или с юридическим лицом, с которым оценщик заключил трудовой договор. (В редакции Федерального закона от 27.07.2006 № 157-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 27.07.2006 № 157-ФЗ)\nВ случаях, предусмотренных законодательством Российской Федерации, оценка объекта оценки, в том числе повторная, может быть проведена оценщиком на основании определения суда, арбитражного суда, третейского суда, а также по решению уполномоченного органа.\nСуд, арбитражный суд, третейский суд самостоятельны в выборе оценщика. Расходы, связанные с проведением оценки объекта оценки, а также денежное вознаграждение оценщику подлежат возмещению (выплате) в порядке, установленном законодательством Российской Федерации."],
["10","Обязательные требования к договору на проведение оценки","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2026-08-04","Статья 10. Обязательные требования к договору на проведение оценки\nДоговор на проведение оценки заключается в простой письменной форме.\nДоговор на проведение оценки должен содержать:\nцель оценки;\nописание объекта или объектов оценки, позволяющее осуществить их идентификацию;\nвид определяемой стоимости объекта оценки;\nразмер денежного вознаграждения за проведение оценки;\nдату определения стоимости объекта оценки;\nсведения об обязательном страховании гражданской ответственности оценщика в соответствии с настоящим Федеральным законом;\nнаименование саморегулируемой организации оценщиков, членом которой является оценщик, и место нахождения этой организации;\nуказание на стандарты оценочной деятельности, которые будут применяться при проведении оценки;\nуказание на размер, порядок и основания наступления дополнительной ответственности по отношению к ответственности, установленной гражданским законодательством и статьей 24.6 настоящего Федерального закона, оценщика или юридического лица, с которым оценщик заключил трудовой договор;\nсведения о договоре страхования ответственности юридического лица, с которым оценщик заключил трудовой договор, за нарушение требований договора на проведение оценки и договора страхования ответственности за причинение вреда имуществу третьих лиц в результате нарушения требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности;\nабзац; (Утратил силу - Федеральный закон от 03.07.2016 № 360-ФЗ)\nсведения о независимости юридического лица, с которым оценщик заключил трудовой договор, и оценщика в соответствии с требованиями статьи 16 настоящего Федерального закона.\n(Часть в редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nВ договоре на проведение оценки, заключенном заказчиком с юридическим лицом, должны быть указаны сведения об оценщике или оценщиках, которые будут проводить оценку, в том числе фамилия, имя, отчество оценщика или оценщиков.\nЧасть. (Утратила силу - Федеральный закон от 28.12.2010 № 431-ФЗ)\nВ отношении оценки объектов, принадлежащих Российской Федерации, субъектам Российской Федерации или муниципальным образованиям, договор на проведение оценки от имени заказчика заключается лицом, уполномоченным собственником на совершение сделок с объектами, если иное не установлено законодательством Российской Федерации.\nДоговор на проведение оценки имущества, находящегося в собственности Российской Федерации, заключается заказчиком только с юридическим лицом, включенным в перечень юридических лиц, предусмотренный пунктом 2 части второй статьи 15.1 настоящего Федерального закона. (Дополнение частью - Федеральный закон от 04.08.2026 № 278-ФЗ)\nДатой определения стоимости объекта оценки (датой проведения оценки, датой оценки) является дата, по состоянию на которую определена стоимость объекта оценки. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["11","Общие требования к содержанию отчета об оценке объекта оценки","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-07-03","Статья 11. Общие требования к содержанию отчета об оценке объекта оценки\nИтоговым документом, составленным по результатам определения стоимости объекта оценки независимо от вида определенной стоимости, является отчет об оценке объекта оценки (далее также - отчет). (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)\nОтчет составляется на бумажном носителе и (или) в форме электронного документа в соответствии с требованиями федеральных стандартов оценки, нормативных правовых актов уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности.\nОтчет не должен допускать неоднозначное толкование или вводить в заблуждение. В отчете в обязательном порядке указываются дата проведения оценки объекта оценки, используемые стандарты оценки, цели и задачи проведения оценки объекта оценки, а также иные сведения, необходимые для полного и недвусмысленного толкования результатов проведения оценки объекта оценки, отраженных в отчете.\nВ отчете должны быть указаны:\nдата составления и порядковый номер отчета;\nоснование для проведения оценщиком оценки объекта оценки;\nсведения об оценщике или оценщиках, проводивших оценку, в том числе фамилия, имя и (при наличии) отчество, номер контактного телефона, почтовый адрес, адрес электронной почты оценщика и сведения о членстве оценщика в саморегулируемой организации оценщиков; (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)\nсведения о независимости юридического лица, с которым оценщик заключил трудовой договор, и оценщика в соответствии с требованиями статьи 16 настоящего Федерального закона; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 360-ФЗ)\nцель оценки;\nточное описание объекта оценки, а в отношении объекта оценки, принадлежащего юридическому лицу, - реквизиты юридического лица и при наличии балансовая стоимость данного объекта оценки; (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)\nстандарты оценки для определения стоимости объекта оценки, перечень использованных при проведении оценки объекта оценки данных с указанием источников их получения, принятые при проведении оценки объекта оценки допущения; (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)\nпоследовательность определения стоимости объекта оценки и ее итоговая величина, ограничения и пределы применения полученного результата;\nдата определения стоимости объекта оценки;\nперечень документов, используемых оценщиком и устанавливающих количественные и качественные характеристики объекта оценки.\nОтчет также может содержать иные сведения, являющиеся, по мнению оценщика, существенно важными для полноты отражения примененного им метода расчета стоимости конкретного объекта оценки.\nДля проведения оценки отдельных видов объектов оценки законодательством Российской Федерации могут быть предусмотрены специальные формы отчетов.\nОтчет должен быть пронумерован постранично, прошит (за исключением случаев составления отчета в форме электронного документа), подписан оценщиком или оценщиками, которые провели оценку, а также скреплен личной печатью оценщика или оценщиков либо печатью юридического лица, с которым оценщик или оценщики заключили трудовой договор.\nОтчет, составленный в форме электронного документа, должен быть подписан усиленной квалифицированной электронной подписью в соответствии с законодательством Российской Федерации.\nВ случаях, предусмотренных настоящим Федеральным законом, нормативными правовыми актами уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, отчет подлежит опубликованию в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\n(Статья в редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["12","Достоверность отчета как документа, содержащего сведения доказательственного значения","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-07-03","Статья 12. Достоверность отчета как документа, содержащего сведения доказательственного значения\nИтоговая величина рыночной или иной стоимости объекта оценки, указанная в отчете, составленном по основаниям и в порядке, которые предусмотрены настоящим Федеральным законом, признается достоверной и рекомендуемой для целей совершения сделки с объектом оценки, если в порядке, установленном законодательством Российской Федерации, или в судебном порядке не установлено иное.\nИтоговая величина рыночной или иной стоимости объекта оценки, определенная в отчете, за исключением кадастровой стоимости, является рекомендуемой для целей определения начальной цены предмета аукциона или конкурса, совершения сделки в течение шести месяцев с даты составления отчета, за исключением случаев, предусмотренных законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)"],
["13","Оспоримость сведений, содержащихся в отчете","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2018-11-28","Статья 13. Оспоримость сведений, содержащихся в отчете\nВ случае наличия спора о достоверности величины рыночной или иной стоимости объекта оценки, установленной в отчете, в том числе и в связи с имеющимся иным отчетом об оценке этого же объекта, указанный спор подлежит рассмотрению судом, арбитражным судом в соответствии с установленной компетенцией, третейским судом по соглашению сторон спора или договора или в порядке, установленном законодательством Российской Федерации, регулирующим оценочную деятельность. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\nСуд, арбитражный суд, третейский суд вправе обязать стороны совершить сделку по цене, определенной в ходе рассмотрения спора в судебном заседании, только в случаях обязательности совершения сделки в соответствии с законодательством Российской Федерации."],
["14","Права оценщика","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-06-02","Статья 14. Права оценщика\nОценщик имеет право:\nприменять самостоятельно методы проведения оценки объекта оценки в соответствии со стандартами оценки;\nтребовать от заказчика при проведении обязательной оценки объекта оценки обеспечения доступа в полном объеме к документации, необходимой для осуществления этой оценки;\nполучать разъяснения и дополнительные сведения, необходимые для осуществления данной оценки;\nзапрашивать в письменной или устной форме у третьих лиц информацию, необходимую для проведения оценки объекта оценки, за исключением информации, являющейся государственной или коммерческой тайной; в случае, если отказ в предоставлении указанной информации существенным образом влияет на достоверность оценки объекта оценки, оценщик указывает это в отчете;\nпривлекать по мере необходимости на договорной основе к участию в проведении оценки объекта оценки иных оценщиков либо других специалистов;\nотказаться от проведения оценки объекта оценки в случаях, если заказчик нарушил условия договора, не обеспечил предоставление необходимой информации об объекте оценки либо не обеспечил соответствующие договору условия работы;\nтребовать возмещения расходов, связанных с проведением оценки объекта оценки, и денежного вознаграждения за проведение оценки объекта оценки по определению суда, арбитражного суда или третейского суда; (Дополнение абзацем - Федеральный закон от 14.11.2002 № 143-ФЗ)\nдобровольно приостанавливать право осуществления оценочной деятельности по личному заявлению, направленному в саморегулируемую организацию оценщиков, в порядке, который установлен внутренними документами саморегулируемой организации оценщиков. (Дополнение абзацем - Федеральный закон от 02.06.2016 № 172-ФЗ)"],
["15","Обязанности оценщика","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2014-07-21","Статья 15. Обязанности оценщика\nОценщик обязан:\nбыть членом одной из саморегулируемых организаций оценщиков;\nсоблюдать требования настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, а также требования стандартов и правил оценочной деятельности, утвержденных саморегулируемой организацией оценщиков, членом которой он является;\nсоблюдать правила деловой и профессиональной этики, установленные саморегулируемой организацией оценщиков (далее - правила деловой и профессиональной этики), членом которой он является, а также уплачивать взносы, установленные такой саморегулируемой организацией оценщиков;\nсообщать заказчику или юридическому лицу, с которым он заключил трудовой договор, о невозможности своего участия в проведении оценки вследствие возникновения обстоятельств, препятствующих проведению объективной оценки;\nобеспечивать сохранность документов, получаемых от заказчика и третьих лиц в ходе проведения оценки;\nпредставлять заказчику информацию о членстве в саморегулируемой организации оценщиков;\nпредставлять саморегулируемой организации оценщиков информацию о юридическом лице, с которым он заключил трудовой договор, в том числе информацию о соответствии такого юридического лица условиям, установленным статьей 15.1 настоящего Федерального закона, а также сведения о любых изменениях этой информации в течение десяти дней с даты заключения трудового договора и (или) возникновения изменений;\nпредставлять ежеквартально в порядке, установленном внутренними документами саморегулируемой организации оценщиков, информацию о подписанных им в указанный период отчетах с указанием даты составления отчета и его порядкового номера, объекта оценки, вида определенной стоимости;\nпредставлять по требованию заказчика страховой полис и подтверждающий получение профессиональных знаний в области оценочной деятельности документ об образовании;\nне разглашать информацию, в отношении которой установлено требование об обеспечении ее конфиденциальности и которая получена от заказчика в ходе проведения оценки, за исключением случаев, предусмотренных законодательством Российской Федерации;\nхранить копии подписанных им отчетов, а также копии документов и материалов, на основании которых проводилась оценка, на бумажных или электронных носителях либо в форме электронных документов в течение трех лет с даты составления отчета;\nв случаях, предусмотренных законодательством Российской Федерации, предоставлять копии хранящихся отчетов или содержащуюся в них информацию правоохранительным, судебным, иным уполномоченным государственным органам по их требованию;\nпо требованию заказчика предоставлять заверенную саморегулируемой организацией оценщиков выписку из реестра членов саморегулируемой организации оценщиков, членом которой он является.\n(Статья в редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["15.1","Права и обязанности юридического лица, с которым оценщик заключил трудовой договор","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2026-08-04","Статья 15.1. Права и обязанности юридического лица, с которым оценщик заключил трудовой договор\n(Наименование в редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nЮридическое лицо, которое намерено заключить с заказчиком договор на проведение оценки (далее также - оценочная компания), обязано: (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nиметь в штате не менее двух оценщиков, право осуществления оценочной деятельности которых не приостановлено;\nсоблюдать требования настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности и обеспечивать соблюдение указанных требований своими работниками;\nстраховать свою ответственность за нарушение договора на проведение оценки и ответственность за причинение вреда имуществу третьих лиц в результате нарушения требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности на срок не менее чем один год. Страховая сумма, в пределах которой страховщик обязуется произвести выплату страхового возмещения при наступлении каждого страхового случая в течение срока действия договора обязательного страхования ответственности юридического лица, заключившего с заказчиком договор на проведение оценки, не может быть менее чем пять миллионов рублей;\nпредоставлять банковскую гарантию, обеспечивающую надлежащее исполнение обязательств по договору на проведение оценки, в случае, если исполнение обязательств по такому договору должно быть обеспечено банковской гарантией, в случаях, предусмотренных законодательством Российской Федерации или договором на проведение оценки;\nобеспечивать сохранность документов, получаемых от заказчика и третьих лиц в ходе проведения оценки;\nсообщать заказчику о невозможности своего участия в проведении оценки вследствие возникновения обстоятельств, препятствующих проведению объективной оценки;\nпредоставлять по требованию заказчика договор обязательного страхования ответственности оценщика, заключенный в соответствии со статьей 24.7 настоящего Федерального закона;\nне разглашать информацию, в отношении которой установлено требование об обеспечении ее конфиденциальности и которая получена от заказчика в ходе проведения оценки, за исключением случаев, предусмотренных законодательством Российской Федерации;\nпредоставлять саморегулируемой организации оценщиков, членом которой является оценщик, для проведения контроля за осуществлением им оценочной деятельности доступ к отчетам, документам и материалам, на основании которых проводилась оценка, за исключением информации, которая составляет коммерческую тайну юридического лица или заказчика, либо иной информации, в отношении которой установлено требование об обеспечении ее конфиденциальности;\nпредоставлять в случаях, предусмотренных законодательством Российской Федерации, копии хранящихся отчетов или содержащуюся в них информацию правоохранительным, судебным, иным уполномоченным государственным органам по их требованиям;\nхранить копию отчета или копии отчетов и копии документов, полученных от заказчика, третьих лиц и использованных при проведении оценки объекта оценки, на бумажных или электронных носителях либо в форме электронных документов в течение трех лет с даты составления отчета;\nпредоставлять оценщику, с которым юридическое лицо заключило трудовой договор, информацию о несоответствии этого юридического лица требованиям настоящей статьи, а также сведения о любых изменениях указанной информации не позднее трех дней с даты возникновения таких несоответствий и (или) изменений.\nПравительство Российской Федерации для оценки имущества, находящегося в собственности Российской Федерации:\n1) устанавливает дополнительные требования к юридическим лицам, которые соответствуют условиям, установленным настоящей статьей, и вправе оказывать услуги по оценке такого имущества в целях осуществления имущественных и иных прав и обеспечения законных интересов Российской Федерации;\n2) утверждает перечень юридических лиц, указанных в пункте 1 настоящей части;\n3) устанавливает порядок подтверждения соответствия юридических лиц, указанных в пункте 1 настоящей части, требованиям, указанным в пункте 1 настоящей части, а также порядок включения таких юридических лиц в перечень юридических лиц, указанный в пункте 2 настоящей части, основания и порядок исключения из него таких юридических лиц. (Дополнение пунктом - Федеральный закон от 04.08.2026 № 278-ФЗ)\n(Дополнение частью - Федеральный закон от 04.07.2026 № 240-ФЗ)\nЮридическое лицо, заключившее с заказчиком договор на проведение оценки, вправе:\nзапрашивать у заказчика оценки необходимые для проведения оценки информацию и документацию;\nотказаться от проведения оценки объекта оценки и расторгнуть договор на проведение оценки в случае, если заказчик не обеспечил предоставление необходимой информации об объекте оценки либо не обеспечил соответствующие договору условия работы.\n(Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["15.2","Права и обязанности заказчика оценки","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-06-02","Статья 15.2. Права и обязанности заказчика оценки\nПри проведении оценки заказчик оценки вправе:\nтребовать и получать от оценочной компании, оценщика обоснование выводов по результатам оценки;\nполучать от оценочной компании, оценщика отчет об оценке в срок, установленный договором на проведение оценки;\nосуществлять иные права, вытекающие из договора на проведение оценки.\nПри проведении оценки заказчик оценки обязан:\nсодействовать оценочной компании, оценщику в своевременном и полном проведении оценки, создавать для этого соответствующие условия, предоставлять необходимые информацию и документацию, давать по устному или письменному запросу оценочной компании, оценщика исчерпывающие разъяснения и подтверждения в устной и письменной форме, а также запрашивать необходимые для проведения оценки сведения у третьих лиц;\nне предпринимать каких бы то ни было действий, направленных на сокрытие (ограничение доступа) информации и документации, запрашиваемых оценочной компанией, оценщиком. Наличие в запрашиваемых оценочной компанией, оценщиком для проведения оценки информации и документации сведений, содержащих коммерческую тайну, не может являться основанием для отказа в их предоставлении;\nсвоевременно оплачивать услуги оценочной компании, оценщика в соответствии с договором на проведение оценки, в том числе в случае, если результаты проведения оценки не согласуются с позицией заказчика оценки;\nисполнять требования настоящего Федерального закона, федеральных стандартов оценки и иные обязанности, вытекающие из договора на проведение оценки.\n(Дополнение статьей - Федеральный закон от 02.06.2016 № 172-ФЗ)"],
["16","Независимость оценщика и юридического лица, с которым оценщик заключил трудовой договор","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-06-02","Статья 16. Независимость оценщика и юридического лица, с которым оценщик заключил трудовой договор\n(Наименование в редакции Федерального закона от 22.07.2010 № 167-ФЗ)\nОценка объекта оценки не может проводиться оценщиком, если он является учредителем, собственником, акционером, должностным лицом или работником юридического лица - заказчика, лицом, имеющим имущественный интерес в объекте оценки, либо состоит с указанными лицами в близком родстве или свойстве. (В редакции Федерального закона от 27.07.2006 № 157-ФЗ)\nПроведение оценки объекта оценки не допускается, если:\nв отношении объекта оценки оценщик имеет вещные или обязательственные права вне договора;\nоценщик является участником (членом) или кредитором юридического лица - заказчика либо такое юридическое лицо является кредитором или страховщиком оценщика. (В редакции Федерального закона от 27.07.2006 № 157-ФЗ)\nНе допускается вмешательство заказчика либо иных заинтересованных лиц в деятельность оценщика и юридического лица, с которым оценщик заключил трудовой договор, если это может негативно повлиять на достоверность результата проведения оценки объекта оценки, в том числе ограничение круга вопросов, подлежащих выяснению или определению при проведении оценки объекта оценки. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nРазмер оплаты оценщику за проведение оценки объекта оценки не может зависеть от итоговой величины стоимости объекта оценки.\nЮридическое лицо не вправе заключать договор на проведение оценки с заказчиком в случаях, если оно имеет имущественный интерес в объекте оценки и (или) является аффилированным лицом заказчика, а также в иных случаях, установленных законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 22.07.2010 № 167-ФЗ)\nРазмер денежного вознаграждения за проведение оценки объекта оценки не может зависеть от итоговой величины стоимости объекта оценки. (Дополнение частью - Федеральный закон от 22.07.2010 № 167-ФЗ)\nОсобенности применения предусмотренных настоящей статьей правил независимости оценщика и юридического лица, с которым оценщик заключил трудовой договор, при определении кадастровой стоимости устанавливаются федеральным стандартом оценки. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)"],
["16.1","(Дополнение статьей - Федеральный закон от 05.01.2006 № 7-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 157-ФЗ)","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2006-07-27","Статья 16.1. (Дополнение статьей - Федеральный закон от 05.01.2006 № 7-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["16.2","Эксперт саморегулируемой организации оценщиков","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-06-02","Статья 16.2. Эксперт саморегулируемой организации оценщиков\nЭкспертом саморегулируемой организации оценщиков - членом экспертного совета саморегулируемой организации оценщиков признается лицо, сдавшее квалификационный экзамен в области оценочной деятельности и избранное в состав экспертного совета саморегулируемой организации оценщиков общим собранием членов саморегулируемой организации оценщиков. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 431-ФЗ)\n(Особенности применения статьи 16.2 - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)"],
["17","(Статья утратила силу - Федеральный закон от 27.07.2006 № 157-ФЗ)","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2006-07-27","Статья 17. (Статья утратила силу - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["17.1","Экспертиза отчета","ГЛАВА II. ОСНОВАНИЯ ДЛЯ ОСУЩЕСТВЛЕНИЯ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ И УСЛОВИЯ ЕЕ ОСУЩЕСТВЛЕНИЯ","2016-06-02","Статья 17.1. Экспертиза отчета\nДля целей настоящего Федерального закона под экспертизой отчета понимаются действия эксперта или экспертов саморегулируемой организации оценщиков в целях формирования мнения эксперта или экспертов в отношении отчета, подписанного оценщиком или оценщиками, о соответствии требованиям законодательства Российской Федерации об оценочной деятельности (в том числе требованиям настоящего Федерального закона, федеральных стандартов оценки и других актов уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности), а в случае проведения экспертизы отчета об определении рыночной стоимости объекта оценки также о подтверждении рыночной стоимости объекта оценки, определенной оценщиком в отчете. Экспертиза отчета проводится на добровольной основе на основании договора между заказчиком экспертизы и саморегулируемой организацией оценщиков. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nЭкспертиза отчета не является контролем, осуществляемым в соответствии со статьей 24.3 настоящего Федерального закона. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nОсобенности проведения экспертизы отчета об определении отдельного вида стоимости объекта оценки (в частности, кадастровой стоимости), в том числе в части подтверждения стоимости объекта оценки (далее - особенности проведения экспертизы отчета), устанавливаются федеральным стандартом оценки.\nРезультатом экспертизы отчета является положительное или отрицательное экспертное заключение, подготовленное экспертом или экспертами саморегулируемой организации оценщиков.\nПоложительным экспертным заключением признается экспертное заключение, содержащее вывод о соответствии отчета требованиям законодательства Российской Федерации об оценочной деятельности (в том числе требованиям настоящего Федерального закона, федеральных стандартов оценки и других актов уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности), стандартов и правил оценочной деятельности, а в случае проведения экспертизы отчета об определении рыночной стоимости объекта оценки или в случаях, установленных федеральными стандартами оценки, также вывод о подтверждении стоимости объекта оценки, определенной оценщиком в отчете.\nПорядок проведения экспертизы отчета, требования к экспертному заключению и порядку его утверждения устанавливаются федеральным стандартом оценки.\nЧасть. (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nДействия (бездействие) эксперта или экспертов саморегулируемой организации оценщиков при проведении экспертизы отчета, результаты такой экспертизы могут быть обжалованы заинтересованными лицами в саморегулируемую организацию оценщиков в порядке и в сроки, которые установлены требованиями к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, утверждаемыми уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности, или оспорены в судебном порядке.\nЭкспертиза отчета может проводиться экспертом по направлению, указанному в квалификационном аттестате и соответствующему объекту оценки. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 08.06.2015 № 145-ФЗ)"],
["18","Регулирование оценочной деятельности и деятельности саморегулируемых организаций оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2021-06-11","Статья 18. Регулирование оценочной деятельности и деятельности саморегулируемых организаций оценщиков\nГосударственное регулирование оценочной деятельности и деятельности саморегулируемых организаций оценщиков в части федерального государственного надзора за деятельностью саморегулируемых организаций оценщиков (далее - надзор за деятельностью саморегулируемых организаций оценщиков) и нормативно-правового регулирования осуществляется федеральными органами исполнительной власти, уполномоченными Правительством Российской Федерации (далее также - уполномоченные федеральные органы). (В редакции федеральных законов от 21.07.2014 № 225-ФЗ, от 11.06.2021 № 170-ФЗ)\nРегулирование оценочной деятельности осуществляется советом по оценочной деятельности при уполномоченном федеральном органе, осуществляющем функции по нормативно-правовому регулированию оценочной деятельности (далее - совет по оценочной деятельности), а также национальным объединением саморегулируемых организаций оценщиков в части разработки федеральных стандартов оценки, за исключением случаев нарушения сроков, предусмотренных программой разработки федеральных стандартов оценки, саморегулируемыми организациями оценщиков в части разработки и утверждения стандартов и правил оценочной деятельности. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nКонтроль за деятельностью членов саморегулируемых организаций оценщиков в части соблюдения ими требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики осуществляется этими саморегулируемыми организациями. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["19","Функции уполномоченных федеральных органов","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 19. Функции уполномоченных федеральных органов\nФункциями уполномоченных федеральных органов являются:\nвыработка государственной политики в области оценочной деятельности;\nнормативно-правовое регулирование в области оценочной деятельности;\nформирование и утверждение программы разработки федеральных стандартов оценки и внесения изменений в федеральные стандарты оценки (далее - программа разработки федеральных стандартов оценки);\nразработка и утверждение федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости, внесение изменений в данные стандарты оценки, разработка и утверждение методических указаний о государственной кадастровой оценке;\nутверждение с учетом рекомендации совета по оценочной деятельности федеральных стандартов оценки и внесение изменений в действующие федеральные стандарты оценки, за исключением федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости;\nразработка федеральных стандартов оценки в случае нарушения национальным объединением саморегулируемых организаций оценщиков сроков, предусмотренных программой разработки федеральных стандартов оценки, за исключением федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости;\nведение единого государственного реестра саморегулируемых организаций оценщиков;\nосуществление надзора за выполнением саморегулируемыми организациями оценщиков требований настоящего Федерального закона;\nобращение в суд с заявлением об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков;\nведение реестра квалификационных аттестатов;\nведение сводного реестра членов саморегулируемых организаций оценщиков, имеющего информационный характер, и внесение в него сведений, подлежащих представлению саморегулируемой организацией оценщиков в соответствии с абзацем четырнадцатым части второй статьи 22.2 настоящего Федерального закона, в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности;\nвозбуждение дел об административных правонарушениях в отношении саморегулируемых организаций оценщиков и (или) их должностных лиц, рассмотрение таких дел или передача их на рассмотрение в суд; (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nиные функции, предусмотренные настоящим Федеральным законом.\n(Статья в редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["19.1","Совет по оценочной деятельности","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-07-03","Статья 19.1. Совет по оценочной деятельности\nСовет по оценочной деятельности создается при уполномоченном федеральном органе, осуществляющем функции по нормативно-правовому регулированию оценочной деятельности.\nСовет по оценочной деятельности осуществляет следующие функции:\nучаствует в рассмотрении вопросов государственной политики в области оценочной деятельности;\nрассматривает проекты федеральных стандартов оценки и рекомендует или не рекомендует их для утверждения уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности;\nрассматривает предложения о совершенствовании деятельности саморегулируемых организаций оценщиков и при необходимости дает рекомендации по совершенствованию этой деятельности;\nвносит на рассмотрение уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, типовые правила профессиональной этики оценщиков и требования к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики;\nрассматривает обращения и ходатайства саморегулируемых организаций оценщиков в области оценочной деятельности и вносит соответствующие предложения на рассмотрение уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности;\nодобряет методические рекомендации по оценке, разработанные в целях развития положений утвержденных федеральных стандартов оценки, за исключением федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости; (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nиные функции, предусмотренные положением о совете по оценочной деятельности. (Дополнение абзацем - Федеральный закон от 02.06.2016 № 172-ФЗ)\nСостав совета по оценочной деятельности утверждается руководителем уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности.\nВ состав совета по оценочной деятельности входят:\nсемь представителей потребителей оценочных услуг - юридических лиц (в том числе кредитных организаций), не менее чем два из которых подлежат ротации один раз в год. Кандидатуры указанных представителей, в том числе в целях ротации, выдвигаются некоммерческими организациями, основанными на членстве и объединяющими потребителей оценочных услуг;\nдва представителя уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности;\nодин представитель уполномоченного федерального органа исполнительной власти, осуществляющего функции по надзору за деятельностью саморегулируемых организаций оценщиков;\nсемь представителей саморегулируемых организаций оценщиков, не менее чем два из которых подлежат ротации один раз в год. Кандидатуры представителей саморегулируемых организаций оценщиков, в том числе в целях ротации, выдвигаются национальным объединением саморегулируемых организаций оценщиков, иными объединениями саморегулируемых организаций оценщиков;\nсемь представителей юридических лиц, которые соответствуют условиям, установленным статьей 15.1 настоящего Федерального закона. Не менее чем два из указанных представителей подлежат ротации один раз в год. Кандидатуры указанных представителей, в том числе в целях ротации, выдвигаются некоммерческими организациями, основанными на членстве и объединяющими этих юридических лиц;\nодин представитель уполномоченного федерального органа исполнительной власти, осуществляющего функции в области приватизации и полномочия собственника, в том числе права акционера акционерного общества и участника общества с ограниченной ответственностью, в сфере управления имуществом Российской Федерации; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 360-ФЗ)\nодин представитель Центрального банка Российской Федерации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 360-ФЗ)\nПредседателем совета по оценочной деятельности является руководитель уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, который входит в совет по оценочной деятельности по должности.\nРешения совета по оценочной деятельности принимаются простым большинством голосов, и его заседание является правомочным, если на нем присутствует не менее чем пятьдесят процентов общего числа его членов.\nВ целях подготовки решений совета по оценочной деятельности создаются его рабочие органы, члены которых не могут быть членами совета по оценочной деятельности.\nСведения о деятельности совета по оценочной деятельности и его рабочих органов являются открытыми, общедоступными и подлежат обязательному размещению на официальном сайте уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, в информационно-телекоммуникационной сети \"Интернет\".\nПоложение о совете по оценочной деятельности, включающее в себя в том числе порядок формирования состава совета по оценочной деятельности, ротации его членов и определяющее порядок работы совета по оценочной деятельности, и положение о его рабочих органах утверждаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nЧлен совета по оценочной деятельности может быть исключен из его состава по решению председателя совета по оценочной деятельности. (Дополнение частью - Федеральный закон от 03.07.2016 № 360-ФЗ)\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 225-ФЗ)"],
["20","Стандарты оценочной деятельности","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 20. Стандарты оценочной деятельности\nСтандартами оценочной деятельности определяются требования к порядку проведения оценки и осуществления оценочной деятельности.\nСтандарты оценочной деятельности подразделяются на федеральные стандарты оценки, стандарты и правила оценочной деятельности. Разработка федеральных стандартов оценки осуществляется на основе международных стандартов оценки. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nФедеральные стандарты оценки, за исключением федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости, разрабатываются национальным объединением саморегулируемых организаций оценщиков и (или) саморегулируемыми организациями оценщиков и представляются на рассмотрение в совет по оценочной деятельности в сроки, предусмотренные программой разработки федеральных стандартов оценки. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 21.07.2014 № 225-ФЗ)\nВ случае, если национальное объединение саморегулируемых организаций оценщиков не представило разработанный проект федерального стандарта оценки на рассмотрение в совет по оценочной деятельности в срок, предусмотренный программой разработки федеральных стандартов оценки, проект соответствующего федерального стандарта оценки разрабатывается и после его рассмотрения советом по оценочной деятельности утверждается уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 21.07.2014 № 225-ФЗ)\nУполномоченный федеральный орган, осуществляющий функции по нормативно-правовому регулированию оценочной деятельности, отказывает в утверждении федеральных стандартов оценки в случае, если разработка представленного проекта федерального стандарта оценки не предусмотрена программой разработки федеральных стандартов оценки, а также в случае их несоответствия требованиям международных договоров Российской Федерации, Конституции Российской Федерации, настоящего Федерального закона, других федеральных законов, иных нормативных правовых актов Российской Федерации об оценочной деятельности. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nУтвержденные федеральные стандарты оценки подлежат опубликованию уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности, в порядке, установленном Правительством Российской Федерации, и размещению на официальном сайте уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, в информационно-телекоммуникационной сети \"Интернет\". (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\nУтвержденные федеральные стандарты оценки и методические указания о государственной кадастровой оценке не подлежат государственной регистрации.\nСтандарты и правила оценочной деятельности разрабатываются и утверждаются саморегулируемой организацией оценщиков и не могут противоречить настоящему Федеральному закону и федеральным стандартам оценки, методическим указаниям о государственной кадастровой оценке. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Статья в редакции Федерального закона от 28.12.2010 № 431-ФЗ)"],
["20.1","Типовые правила профессиональной этики оценщиков и требования к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 20.1. Типовые правила профессиональной этики оценщиков и требования к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики\nПравила деловой и профессиональной этики должны включать в себя положения типовых правил профессиональной этики оценщиков, утвержденных уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности, по представлению совета по оценочной деятельности.\nСаморегулируемая организация оценщиков вправе включить в принимаемые ею правила деловой и профессиональной этики дополнительные требования.\nУполномоченный федеральный орган, осуществляющий функции по нормативно-правовому регулированию оценочной деятельности, отказывает в утверждении представленных советом по оценочной деятельности типовых правил профессиональной этики оценщиков, требований к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики в случае их несоответствия требованиям международных договоров Российской Федерации, Конституции Российской Федерации, настоящего Федерального закона, других федеральных законов, иных нормативных правовых актов Российской Федерации в области оценочной деятельности. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nПроцедура рассмотрения жалобы на действия члена саморегулируемой организации оценщиков (далее - жалоба) и дела о нарушении членом саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, требований о внесении обязательных взносов в саморегулируемую организацию оценщиков и дополнительных требований к порядку обеспечения имущественной ответственности членов саморегулируемой организации оценщиков определяется внутренними документами саморегулируемой организации оценщиков, которые должны соответствовать положениям требований к рассмотрению саморегулируемой организацией оценщиков жалобы на нарушение ее членом требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, утверждаемых уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности, и включающих в себя в том числе требования к содержанию жалоб, порядок и сроки их рассмотрения, порядок и основания применения к члену саморегулируемой организации оценщиков мер дисциплинарного воздействия (далее - требования к рассмотрению жалоб). (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 225-ФЗ)"],
["21","Образование оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 21. Образование оценщиков\nОбразование оценщиков осуществляется по образовательным программам высшего образования, дополнительным профессиональным программам образовательными организациями в соответствии с законодательством Российской Федерации.\n(Статья в редакции Федерального закона от 18.03.2020 № 66-ФЗ)"],
["21.1","Квалификационный экзамен в области оценочной деятельности","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 21.1. Квалификационный экзамен в области оценочной деятельности\nКвалификационный экзамен в области оценочной деятельности (далее - квалификационный экзамен) проводится уполномоченным Правительством Российской Федерации органом (далее - орган, уполномоченный на проведение квалификационного экзамена) в целях подтверждения уровня квалификации.\nПеречень экзаменационных вопросов для проведения квалификационного экзамена формируется органом, уполномоченным на проведение квалификационного экзамена. Порядок формирования перечня экзаменационных вопросов, проведения и сдачи квалификационного экзамена, предусматривающий в том числе порядок участия претендента в квалификационном экзамене, порядок определения результатов квалификационного экзамена, порядок подачи и рассмотрения апелляций, утверждается уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nЗа прием квалификационного экзамена с претендента может взиматься плата, размер и порядок взимания которой устанавливаются органом, уполномоченным на проведение квалификационного экзамена. Предельный размер платы, взимаемой с претендента за прием квалификационного экзамена, устанавливается уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nК квалификационному экзамену допускается претендент, получивший высшее образование и (или) профессиональную переподготовку в области оценочной деятельности.\nК повторной сдаче квалификационного экзамена претендент допускается не ранее чем через тридцать дней. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nПолномочия органа, уполномоченного на проведение квалификационного экзамена, на основании его решения вправе осуществлять подведомственная ему организация. (Дополнение частью - Федеральный закон от 03.07.2016 № 360-ФЗ)\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Особенности применения статьи 21.12 - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)"],
["21.2","Квалификационный аттестат","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 21.2. Квалификационный аттестат\nКвалификационный аттестат является свидетельством, подтверждающим сдачу квалификационного экзамена, и выдается при условии, что лицо, претендующее на его получение, сдало квалификационный экзамен.\nТипы, формы квалификационных аттестатов, порядок их выдачи и аннулирования, порядок ведения реестра квалификационных аттестатов уполномоченным федеральным органом, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, утверждаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nКвалификационный аттестат выдается органом, уполномоченным на проведение квалификационного экзамена, при условии, что лицо, претендующее на его получение (далее - претендент):\nсдало квалификационный экзамен;\nимеет на дату подачи заявления о выдаче квалификационного аттестата стаж (опыт) работы, связанной с осуществлением оценочной деятельности, не менее трех лет. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\n(Особенности применения абзаца - Федеральный закон от 18.03.2020 № 66-ФЗ)\nРешение об отказе в выдаче квалификационного аттестата принимается в случае, если:\nпретендент не соответствует требованиям части третьей настоящей статьи;\nпосле сдачи квалификационного экзамена обнаруживается несоответствие претендента требованию абзаца третьего части третьей настоящей статьи.\nКвалификационный аттестат выдается на три года и действует в течение указанного срока. Орган, уполномоченный на проведение квалификационного экзамена, не вправе выдвигать какие-либо требования или условия при выдаче квалификационного аттестата, за исключением установленных настоящим Федеральным законом.\nДатой выдачи квалификационного аттестата считается дата принятия органом, уполномоченным на проведение квалификационного экзамена, решения о выдаче аттестата.\nРешение об отказе в выдаче квалификационного аттестата может быть оспорено в суде.\nОценщик в течение каждых трех календарных лет начиная с года, следующего за годом получения квалификационного аттестата, обязан подтверждать квалификацию путем сдачи квалификационного экзамена.\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Особенности применения статьи 21.2 - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)"],
["22","Саморегулируемая организация оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 22. Саморегулируемая организация оценщиков\nСаморегулируемой организацией оценщиков признается некоммерческая организация, созданная в целях регулирования оценочной деятельности и контроля за деятельностью своих членов в части соблюдения ими требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, включенная в единый государственный реестр саморегулируемых организаций оценщиков и объединяющая на условиях членства оценщиков. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nСтатус саморегулируемой организации оценщиков приобретается некоммерческой организацией в соответствии с положениями настоящей статьи с даты ее включения в единый государственный реестр саморегулируемых организаций оценщиков.\nОснованием для включения некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков является выполнение ею следующих требований:\nобъединение в составе этой организации в качестве ее членов не менее чем триста физических лиц, отвечающих требованиям к субъектам оценочной деятельности; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nналичие компенсационного фонда, который формируется за счет взносов ее членов в денежной форме в размере, установленном частью третьей статьи 24.6 настоящего Федерального закона;\nналичие коллегиального органа управления (совета, наблюдательного совета), функционально специализированных органов и структурных подразделений;\nналичие стандартов и правил оценочной деятельности, утвержденных в соответствии с требованиями настоящего Федерального закона;\nналичие официального сайта в информационно-телекоммуникационной сети \"Интернет\", соответствующего требованиям настоящего Федерального закона и Федерального закона от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\". (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nСаморегулируемая организация оценщиков должна соответствовать требованиям части третьей настоящей статьи. При определении соответствия саморегулируемой организации оценщиков требованию об объединении в составе этой организации в качестве ее членов не менее чем триста физических лиц, отвечающих требованиям к субъектам оценочной деятельности, учитываются оценщики, право осуществления оценочной деятельности которых не приостановлено. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nРаботники саморегулируемой организации оценщиков не вправе осуществлять оценочную деятельность.\nСаморегулируемая организация оценщиков обязана своевременно принимать меры по недопущению возникновения конфликта интересов между саморегулируемой организацией оценщиков и ее членами, а также по своевременному урегулированию такого конфликта.\nЛиквидация некоммерческой организации, имеющей статус саморегулируемой организации оценщиков, осуществляется в соответствии с законодательством о некоммерческих организациях. В ликвидационную комиссию некоммерческой организации, имеющей статус саморегулируемой организации оценщиков, должен быть включен представитель национального объединения саморегулируемых организаций оценщиков (при наличии). (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nНекоммерческая организация, имеющая статус саморегулируемой организации оценщиков, может быть реорганизована только в форме присоединения одной саморегулируемой организации оценщиков к другой саморегулируемой организации оценщиков в порядке, установленном законодательством Российской Федерации. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nЧлены присоединенной саморегулируемой организации оценщиков становятся членами саморегулируемой организации оценщиков, к которой присоединилась саморегулируемая организация оценщиков (далее - реорганизованная саморегулируемая организация оценщиков), с момента внесения в единый государственный реестр юридических лиц записи о прекращении деятельности присоединенной саморегулируемой организации оценщиков. Члены присоединенной саморегулируемой организации оценщиков в течение шести месяцев с указанного момента обязаны подтвердить соответствие требованиям реорганизованной саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["22.1","Функции саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 22.1. Функции саморегулируемой организации оценщиков\nФункциями саморегулируемой организации оценщиков являются:\nразработка и утверждение стандартов и правил оценочной деятельности; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nразработка правил деловой и профессиональной этики в соответствии с типовыми правилами профессиональной этики оценщиков; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nразработка и утверждение правил и условий приема в члены саморегулируемой организации оценщиков, дополнительных требований к порядку обеспечения имущественной ответственности своих членов при осуществлении оценочной деятельности, установление размера членских взносов и порядка их внесения;\nпредставление интересов своих членов в их отношениях с федеральными органами государственной власти, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, а также с международными профессиональными организациями оценщиков;\nприем в члены и прекращение членства в саморегулируемой организации оценщиков по основаниям, предусмотренным настоящим Федеральным законом и внутренними документами саморегулируемой организации оценщиков; (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nконтроль за деятельностью своих членов в части соблюдения ими требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nведение реестра членов саморегулируемой организации оценщиков и предоставление доступа к информации, содержащейся в этом реестре, заинтересованным лицам с соблюдением требований настоящего Федерального закона, Федерального закона от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\" и принятых в соответствии с ними иных нормативных правовых актов Российской Федерации; (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nорганизация информационного и методического обеспечения своих членов;\nосуществление иных установленных настоящим Федеральным законом функций;\nабзац. (Дополнение абзацем - Федеральный закон от 28.12.2010 № 431-ФЗ) (Утратил силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["22.2","Основные права и обязанности саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 22.2. Основные права и обязанности саморегулируемой организации оценщиков\nСаморегулируемая организация оценщиков вправе:\nпредставлять интересы своих членов в их отношениях с федеральными органами государственной власти, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, а также с международными профессиональными организациями оценщиков;\nоспаривать в судебном порядке акты федеральных органов государственной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления и действия (бездействие) этих органов, нарушающие права и законные интересы всех или части своих членов.\nСаморегулируемая организация оценщиков обязана:\nсоблюдать требования настоящего Федерального закона, других федеральных законов и иных нормативных правовых актов Российской Федерации;\nформировать компенсационный фонд для обеспечения ответственности своих членов перед потребителями услуг в области оценочной деятельности и третьими лицами, а также размещать средства компенсационного фонда на условиях и в порядке, которые установлены статьей 24.9 настоящего Федерального закона; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nосуществлять контроль за соблюдением своими членами требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nутвердить в соответствии с требованиями к рассмотрению жалоб внутренние документы саморегулируемой организации оценщиков, в том числе в части установления мер дисциплинарного воздействия при несоблюдении членом саморегулируемой организации оценщиков требований, предусмотренных настоящим Федеральным законом, федеральными стандартами оценки, иными нормативными правовыми актами Российской Федерации в области оценочной деятельности, стандартами и правилами оценочной деятельности, правилами деловой и профессиональной этики; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nприменять меры дисциплинарного воздействия, предусмотренные настоящим Федеральным законом, требованиями к рассмотрению жалоб и внутренними документами саморегулируемой организации оценщиков, в отношении своих членов; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nсообщать в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, о возникновении своего несоответствия требованиям, предусмотренным частью третьей статьи 22 настоящего Федерального закона, в течение десяти дней с момента выявления такого несоответствия;\nотказать в принятии в члены саморегулируемой организации оценщиков в случаях, установленных настоящим Федеральным законом;\nисключать из членов саморегулируемой организации оценщиков по основаниям, предусмотренным настоящим Федеральным законом, за нарушение требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nвести реестр членов саморегулируемой организации оценщиков и предоставлять доступ к информации, содержащейся в этом реестре, заинтересованным лицам с соблюдением требований настоящего Федерального закона, Федерального закона от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\" и принятых в соответствии с ними иных нормативных правовых актов Российской Федерации; (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nорганизовывать проведение профессиональной переподготовки оценщиков;\nабзац; (Дополнение абзацем - Федеральный закон от 28.12.2010 № 431-ФЗ) (Утратил силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nпредставлять в уполномоченный федеральный орган исполнительной власти, осуществляющий ведение единого государственного реестра саморегулируемых организаций оценщиков, информацию о вступлении в национальное объединение саморегулируемых организаций оценщиков и выходе из него в срок, не превышающий трех рабочих дней с даты такого вступления или такого выхода; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nпредставлять в уполномоченный федеральный орган исполнительной власти, осуществляющий ведение сводного реестра членов саморегулируемых организаций оценщиков, сведения о внесении изменений в реестр членов саморегулируемой организации оценщиков и об основаниях внесения таких изменений в срок не более чем пять рабочих дней с даты внесения таких изменений в форме и в порядке, которые установлены уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nрассматривать жалобы и дела о нарушении членами саморегулируемой организации оценщиков требований настоящего Федерального закона, других федеральных законов, иных нормативных правовых актов Российской Федерации, федеральных стандартов оценки, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nхранить все поступившие в саморегулируемую организацию оценщиков жалобы и материалы проверки в течение пяти лет, вести учет жалоб, отвечающих требованиям к рассмотрению жалоб, в порядке, установленном внутренними документами саморегулируемой организации оценщиков, с указанием информации о заявителе, члене саморегулируемой организации оценщиков, в отношении которого поступила жалоба, даты поступления, предмета жалобы, срока и результата рассмотрения жалобы. (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["22.3","Раскрытие информации саморегулируемой организацией оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2015-06-08","Статья 22.3. Раскрытие информации саморегулируемой организацией оценщиков\nСаморегулируемая организация оценщиков наряду с информацией, предусмотренной Федеральным законом от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\", обязана разместить на официальном сайте саморегулируемой организации оценщиков в информационно-телекоммуникационной сети \"Интернет\": (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nучредительные документы;\nправила деловой и профессиональной этики; (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nположения о коллегиальном органе управления саморегулируемой организации оценщиков, о структурном подразделении, осуществляющем контроль за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, об органе по рассмотрению дел о применении дисциплинарных взысканий в отношении членов этой организации (далее - дисциплинарный комитет), об иных органах и структурных подразделениях и информацию о составе таких органов и подразделений; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nинформацию о несоответствии саморегулируемой организации оценщиков установленным частью третьей статьи 22 настоящего Федерального закона требованиям (в том числе информацию о дате возникновения несоответствия саморегулируемой организации оценщиков указанным требованиям, о мерах, предпринимаемых и (или) планируемых саморегулируемой организацией оценщиков для устранения такого несоответствия);\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nинформацию об отчетах своих членов, дата составления которых предшествует не более чем на три года дате размещения указанной информации, с разбивкой по годам и указанием даты составления и порядкового номера отчета, объекта оценки, вида определенной стоимости объекта оценки, фамилии, имени и (при наличии) отчества оценщика, составившего отчет, или фамилий, имен и (при наличии) отчеств оценщиков, составивших отчет, наименования юридического лица, заключившего договор на проведение оценки (при наличии); (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nинформацию о приобретении должностными лицами или работниками саморегулируемой организации оценщиков или их аффилированными лицами ценных бумаг, эмитентами которых или должниками по которым являются юридические лица, с которыми члены саморегулируемой организации оценщиков заключили трудовые договоры;\nабзац; (Утратил силу - Федеральный закон от 07.06.2013 № 113-ФЗ)\nинформацию о возникновении конфликта интересов между саморегулируемой организацией оценщиков и ее членами;\nинформацию о поступивших в саморегулируемую организацию оценщиков жалобах, отвечающих требованиям к рассмотрению жалоб, с указанием фамилии, имени и (при наличии) отчества члена саморегулируемой организации оценщиков, в отношении которого поступила жалоба, даты поступления, предмета жалобы, срока и результата рассмотрения жалобы, при наличии решения о применении меры дисциплинарного воздействия; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nинформацию о приостановлении права осуществления оценочной деятельности членом саморегулируемой организации оценщиков, в том числе о периоде и об основаниях приостановления такого права; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 08.06.2015 № 145-ФЗ)\nинформацию о юридическом лице, с которым оценщик заключил трудовой договор, в том числе о соответствии этого юридического лица требованиям настоящего Федерального закона; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ)\nинформацию об утвержденном размере платы за проведение экспертизы отчета, о порядке проведения экспертизы отчета и о результатах экспертизы, проведенной ее членами, с указанием даты составления и порядкового номера отчета, даты составления и порядкового номера экспертного заключения, сведений об эксперте или экспертах (фамилия, имя и (при наличии) отчество), проводивших такую экспертизу, вывода, полученного в результате проведения такой экспертизы. (Дополнение абзацем - Федеральный закон от 08.06.2015 № 145-ФЗ)\nСаморегулируемая организация оценщиков обязана разместить на официальном сайте саморегулируемой организации оценщиков в информационно-телекоммуникационной сети \"Интернет\" все изменения, внесенные в документы, или изменение информации, определенной частью первой настоящей статьи, не позднее дня, следующего за днем, когда такие изменения были приняты, произошли или стали известны саморегулируемой организации оценщиков. (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\nСаморегулируемая организация оценщиков обязана разработать и утвердить положение о раскрытии информации, в котором с учетом требований настоящего Федерального закона и Федерального закона от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\" устанавливаются: (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nпорядок представления отчетности в саморегулируемую организацию оценщиков ее членами, объем содержания такой отчетности;\nобъем публикуемой информации об отчетах членов саморегулируемой организации оценщиков;\nпорядок предоставления информации, содержащейся в реестре членов саморегулируемой организации оценщиков, по запросам граждан и юридических лиц;\nиные не противоречащие настоящей статье требования.\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["23","Порядок включения некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2025-07-31","Статья 23. Порядок включения некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков\nНекоммерческая организация, удовлетворяющая требованиям части третьей статьи 22 настоящего Федерального закона, вправе подать в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, с использованием информационно-телекоммуникационных сетей, в том числе информационно-телекоммуникационной сети \"Интернет\", включая федеральную государственную информационную систему \"Единый портал государственных и муниципальных услуг (функций)\" (далее - единый портал государственных и муниципальных услуг), в форме электронного документа заявление о своем включении в единый государственный реестр саморегулируемых организаций оценщиков. За включение некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков уплачивается государственная пошлина в размерах и порядке, которые установлены законодательством Российской Федерации о налогах и сборах. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nДля включения сведений о некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков некоммерческая организация представляет в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, следующие документы: (В редакции Федерального закона от 03.12.2011 № 383-ФЗ)\nзаявление о включении в единый государственный реестр саморегулируемых организаций оценщиков с указанием наименования некоммерческой организации, основного государственного регистрационного номера, идентификационного номера налогоплательщика, адреса официального сайта саморегулируемой организации оценщиков в информационно-телекоммуникационной сети \"Интернет\", адреса электронной почты, наименования созданного коллегиального органа управления некоммерческой организации, информации о наличии специализированных органов, предусмотренных частью двенадцатой статьи 24.2 настоящего Федерального закона, состава участвующих в их работе лиц; (В редакции федеральных законов от 03.12.2011 № 383-ФЗ, от 07.06.2013 № 113-ФЗ, от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 01.07.2011 № 169-ФЗ)\nкопии документов об образовании и (или) о квалификации, подтверждающих получение ее членами профессиональных знаний в области оценочной деятельности в соответствии с образовательными программами высшего образования, дополнительными профессиональными программами в области оценочной деятельности (в случае получения соответствующего образования до 10 июля 1992 года); (В редакции федеральных законов от 13.07.2007 № 129-ФЗ, от 02.07.2013 № 185-ФЗ, от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nкопии стандартов и правил оценочной деятельности; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 01.07.2011 № 169-ФЗ)\nкопии документов, подтверждающих формирование компенсационного фонда в размере, установленном настоящим Федеральным законом; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nкопии заявлений ее членов о вступлении в эту организацию; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nкопия реестра членов некоммерческой организации с указанием идентификационного номера налогоплательщика и данных документа, удостоверяющего личность члена некоммерческой организации (фамилии, имени, отчества (при наличии), даты рождения, места рождения, реквизитов документа, удостоверяющего личность члена некоммерческой организации, страхового номера индивидуального лицевого счета в системе обязательного пенсионного страхования Российской Федерации), каждого из ее членов; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nабзац; (Дополнение абзацем - Федеральный закон от 27.12.2009 № 374-ФЗ) (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nабзац; (Дополнение абзацем - Федеральный закон от 28.12.2010 № 431-ФЗ) (Утратил силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nкопии договоров обязательного страхования ответственности оценщика в отношении каждого члена некоммерческой организации; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nабзац. (Дополнение абзацем - Федеральный закон от 02.06.2016 № 172-ФЗ) (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 01.07.2011 № 169-ФЗ) (Утратила силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nУполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, при рассмотрении заявления о включении некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков запрашивает: (В редакции федеральных законов от 03.12.2011 № 383-ФЗ, от 18.03.2020 № 66-ФЗ, от 31.07.2025 № 304-ФЗ)\nв налоговом органе сведения о постановке некоммерческой организации на учет в налоговом органе;\nв федеральном органе исполнительной власти, осуществляющем функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере внутренних дел, сведения об отсутствии у членов некоммерческой организации неснятой или непогашенной судимости за преступления в сфере экономики, а также за преступления средней тяжести, тяжкие и особо тяжкие преступления;\nв федеральном органе исполнительной власти, осуществляющем государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств, копии учредительных документов некоммерческой организации; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 304-ФЗ)\nв федеральном органе исполнительной власти, осуществляющем государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств, сведения, подтверждающие внесение в единый государственный реестр юридических лиц записи о прекращении деятельности присоединенной некоммерческой организации, имеющей статус саморегулируемой организации оценщиков; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 304-ФЗ)\nв федеральном органе исполнительной власти, уполномоченном на организацию формирования и ведения федеральной информационной системы \"Федеральный реестр сведений о документах об образовании и (или) о квалификации, документах об обучении\", сведения о документах об образовании и (или) о квалификации, выданных организациями, осуществляющими образовательную деятельность, после 10 июля 1992 года, в отношении каждого члена некоммерческой организации. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 304-ФЗ)\n(Дополнение частью - Федеральный закон от 01.07.2011 № 169-ФЗ)\nУполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, принимает решение о включении некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков или решение об отказе во включении некоммерческой организации в такой реестр в течение десяти рабочих дней со дня представления заявления о включении в единый государственный реестр саморегулируемых организаций оценщиков и других документов, предусмотренных частью второй настоящей статьи, о чем некоммерческая организация уведомляется в день принятия соответствующего решения путем направления уведомления в форме электронного документа с использованием информационно-телекоммуникационных сетей, в том числе информационно-телекоммуникационной сети \"Интернет\", включая единый портал государственных и муниципальных услуг. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nРешение уполномоченного федерального органа, осуществляющего функции по надзору за деятельностью саморегулируемых организаций оценщиков, об отказе во включении некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков может быть принято по следующим основаниям:\nнекоммерческая организация не соответствует одному из требований, предусмотренных частью третьей статьи 22 настоящего Федерального закона;\nнекоммерческая организация не представила предусмотренные частью второй настоящей статьи документы, обязанность по представлению которых возложена на некоммерческую организацию или представила документы, содержащие недостоверную информацию; (В редакции Федерального закона от 01.07.2011 № 169-ФЗ)\nв налоговом органе отсутствуют сведения о постановке некоммерческой организации на учет в налоговом органе; (Дополнение абзацем - Федеральный закон от 03.12.2011 № 383-ФЗ)\nв федеральном органе исполнительной власти, осуществляющем государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств, отсутствуют сведения о прекращении деятельности присоединенной некоммерческой организации, имеющей статус саморегулируемой организации. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 304-ФЗ)\nРешение об отказе во включении некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков может быть обжаловано этой некоммерческой организацией в арбитражный суд.\nИсключение саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков осуществляется уполномоченным федеральным органом, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, в случае, если этой организацией подано заявление о ее исключении из указанного реестра, или в случае ликвидации некоммерческой организации, имеющей статус саморегулируемой организации оценщиков, или в случае реорганизации саморегулируемой организации оценщиков путем присоединения к другой саморегулируемой организации оценщиков. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nВ иных случаях уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, обращается в арбитражный суд с заявлением об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков. Основанием для обращения в арбитражный суд является:\nвыявленное по результатам проверки несоответствие саморегулируемой организации оценщиков одному из требований, предусмотренных частью третьей статьи 22 настоящего Федерального закона;\nневыполнение саморегулируемой организацией оценщиков требований об устранении выявленных уполномоченным федеральным органом, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, и указанных в предписании нарушений в установленные им сроки.\nПорядок ведения единого государственного реестра саморегулируемых организаций оценщиков и перечень включаемых в него сведений устанавливаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (Дополнение частью - Федеральный закон от 07.06.2013 № 113-ФЗ)\nСведения, содержащиеся в едином государственном реестре саморегулируемых организаций оценщиков, являются общедоступными, подлежат размещению на официальном сайте уполномоченного федерального органа, осуществляющего функции по надзору за деятельностью саморегулируемых организаций оценщиков, в информационно-телекоммуникационной сети \"Интернет\". Сведения, содержащиеся в едином государственном реестре саморегулируемых организаций оценщиков, используются в иных государственных информационных ресурсах, а также при межведомственном информационном взаимодействии. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nЗаявление уполномоченного федерального органа исполнительной власти, осуществляющего функции по надзору за деятельностью саморегулируемых организаций оценщиков, об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков представляется в суд по месту ведения единого государственного реестра саморегулируемых организаций оценщиков. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\nВ случае реорганизации саморегулируемой организации оценщиков в целях внесения изменений в сведения, содержащиеся в едином государственном реестре саморегулируемых организаций оценщиков, саморегулируемая организация оценщиков, к которой присоединилась другая саморегулируемая организация оценщиков, представляет в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, следующие документы:\nзаявление о внесении изменений в сведения, содержащиеся в едином государственном реестре саморегулируемых организаций оценщиков, с указанием наименования некоммерческой организации, основного государственного регистрационного номера и идентификационного номера налогоплательщика;\nкопии протоколов общих собраний членов саморегулируемых организаций оценщиков, принявших решение о реорганизации в форме присоединения; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nдокументы, предусмотренные абзацами девятым и одиннадцатым части второй настоящей статьи. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\n(Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\nДокументы, указанные в частях первой, второй, восьмой и двенадцатой настоящей статьи, направляются некоммерческой организацией в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, в форме электронных документов (пакета электронных документов) с использованием информационно-телекоммуникационных сетей, в том числе информационно-телекоммуникационной сети \"Интернет\", включая единый портал государственных и муниципальных услуг, и подписываются усиленной квалифицированной электронной подписью в соответствии с требованиями Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\" или подписываются физическим лицом, действующим от имени некоммерческой организации на основании доверенности в электронной форме в машиночитаемом виде, усиленной квалифицированной электронной подписью или усиленной неквалифицированной электронной подписью, сертификат ключа проверки которой создан и используется в инфраструктуре, обеспечивающей информационно-технологическое взаимодействие информационных систем, используемых для предоставления государственных и муниципальных услуг в электронной форме, в установленном Правительством Российской Федерации порядке и при условии организации взаимодействия физического лица с такой инфраструктурой с применением прошедших в установленном порядке процедуру оценки соответствия средств защиты информации. (Дополнение частью - Федеральный закон от 31.07.2025 № 304-ФЗ)\nНекоммерческая организация вместе с документами, указанными в части второй настоящей статьи, вправе по собственной инициативе представить в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, копии учредительных документов, а также копии документов, подтверждающих сведения, предусмотренные частью четвертой настоящей статьи. (Дополнение частью - Федеральный закон от 31.07.2025 № 304-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["24","Требования к членству в саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 24. Требования к членству в саморегулируемой организации оценщиков\nОценщик одновременно может быть членом только одной саморегулируемой организации оценщиков, отвечающей требованиям настоящего Федерального закона.\nОбязательными условиями членства в саморегулируемой организации оценщиков являются:\nналичие высшего образования и (или) профессиональной переподготовки в области оценочной деятельности;\nотсутствие неснятой или непогашенной судимости за преступления в сфере экономики, а также за преступления средней тяжести, тяжкие и особо тяжкие преступления;\nналичие квалификационного аттестата. (Дополнение абзацем - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\nДля вступления в члены саморегулируемой организации оценщиков физическое лицо представляет:\nдокумент об образовании и (или) о квалификации, подтверждающий получение высшего образования по результатам освоения образовательных программ, имеющих направленность (профиль) в области оценочной деятельности, и (или) диплом о профессиональной переподготовке в области оценочной деятельности; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nсправку об отсутствии неснятой или непогашенной судимости за преступления в сфере экономики, а также за преступления средней тяжести, тяжкие и особо тяжкие преступления. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nСаморегулируемая организация оценщиков при приеме физических лиц в члены саморегулируемой организации оценщиков вправе предъявлять иные связанные с осуществлением оценщиком оценочной деятельности и не противоречащие настоящему Федеральному закону и другим федеральным законам требования.\nКоллегиальный орган управления саморегулируемой организации оценщиков принимает решение о соответствии лица требованиям, установленным частями второй и третьей настоящей статьи, в течение семи дней со дня поступления заявления и необходимых документов от такого лица.\nЛицо, в отношении которого принято решение о его соответствии требованиям, установленным частями второй и третьей настоящей статьи, считается принятым в члены саморегулируемой организации оценщиков, и сведения о таком лице вносятся в реестр членов саморегулируемой организации оценщиков в течение трех дней со дня представления таким лицом договора обязательного страхования ответственности, отвечающего требованиям, установленным статьей 24.7 настоящего Федерального закона, и внесения установленных саморегулируемой организацией оценщиков взносов. Такому лицу в течение десяти дней со дня внесения сведений о нем в реестр членов саморегулируемой организации оценщиков выдается документ о членстве в саморегулируемой организации оценщиков.\nОснованием для отказа в принятии лица в члены саморегулируемой организации оценщиков является:\nнесоответствие лица требованиям настоящей статьи;\nнесоответствие лица требованиям, утвержденным саморегулируемой организацией оценщиков для вступления в члены саморегулируемой организации оценщиков;\nисключение лица из членов любой из саморегулируемых организаций оценщиков за нарушение требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, если с даты исключения из членов саморегулируемой организации оценщиков прошло менее чем три года. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nЛицо, которому отказано в приеме в члены саморегулируемой организации оценщиков, вправе обжаловать такой отказ в арбитражный суд.\nЧленство в саморегулируемой организации оценщиков прекращается коллегиальным органом управления саморегулируемой организации оценщиков на основании: (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nзаявления оценщика о выходе из членов саморегулируемой организации оценщиков;\nутверждения коллегиальным органом управления саморегулируемой организации оценщиков решения об исключении лица из членов саморегулируемой организации оценщиков. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nЧленство лица в саморегулируемой организации оценщиков не может быть прекращено до окончания проверки в случае поступления в указанную саморегулируемую организацию жалобы на него, если в отношении члена саморегулируемой организации оценщиков проводится проверка или рассматривается дело о применении меры дисциплинарного воздействия, а в случае выявления нарушений - до окончания рассмотрения дисциплинарным комитетом дела о нарушении и применении меры дисциплинарного воздействия. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nЗапись о прекращении членства в саморегулируемой организации оценщиков вносится в реестр членов саморегулируемой организации оценщиков также в случае поступления в саморегулируемую организацию оценщиков информации, подтверждающей смерть члена саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nЛицо, в отношении которого принято решение о прекращении членства в саморегулируемой организации оценщиков, обязано уведомить о факте прекращения своего членства в саморегулируемой организации оценщиков и невозможности подписания отчета о проведении оценки заказчика по договору на проведение оценки или юридическое лицо, с которым заключен трудовой договор.\nСаморегулируемая организация оценщиков не позднее дня, следующего за днем принятия коллегиальным органом управления саморегулируемой организации оценщиков решения о прекращении членства оценщика в саморегулируемой организации оценщиков, обязана разместить такое решение на официальном сайте саморегулируемой организации оценщиков в информационно-телекоммуникационной сети \"Интернет\", а также направить копии такого решения: (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\nлицу, в отношении которого принято решение о прекращении членства в саморегулируемой организации оценщиков;\nюридическому лицу, с которым лицо заключило трудовой договор, в случаях, если информация о заключенном трудовом договоре ранее представлялась в саморегулируемую организацию оценщиков;\nвсем саморегулируемым организациям, внесенным в единый государственный реестр саморегулируемых организаций оценщиков, и национальному объединению саморегулируемых организаций оценщиков в случае утверждения коллегиальным органом управления саморегулируемой организации оценщиков решения об исключении лица из членов саморегулируемой организации оценщиков в связи с нарушением им требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nуполномоченному федеральному органу исполнительной власти, осуществляющему ведение сводного реестра членов саморегулируемых организаций оценщиков. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\n(Статья в редакции Федерального закона от 27.07.2006 № 157-ФЗ)"],
["24.1","Ведение саморегулируемой организацией оценщиков реестра членов саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2013-06-07","Статья 24.1. Ведение саморегулируемой организацией оценщиков реестра членов саморегулируемой организации оценщиков\nНаряду с требованиями, установленными Федеральным законом от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\", дополнительные требования к составу сведений, включаемых в реестр членов саморегулируемой организации оценщиков, порядок ведения саморегулируемой организацией оценщиков этого реестра и предоставления доступа к информации, содержащейся в этом реестре, заинтересованным лицам утверждаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (В редакции Федерального закона от 07.06.2013 № 113-ФЗ)\nНа основании положений настоящего Федерального закона информация, содержащаяся в реестре членов саморегулируемой организации оценщиков, предоставляется по запросам граждан, юридических лиц в порядке, определенном внутренними документами саморегулируемой организации оценщиков. Срок предоставления такой информации не может превышать семь дней со дня поступления соответствующего запроса.\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.2","Органы саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 24.2. Органы саморегулируемой организации оценщиков\nПорядок формирования, структура, компетенция и срок полномочий органов саморегулируемой организации оценщиков, порядок принятия этими органами решений устанавливаются внутренними документами саморегулируемой организации оценщиков в соответствии с настоящим Федеральным законом и другими федеральными законами.\nОбщее собрание членов саморегулируемой организации оценщиков является высшим органом управления саморегулируемой организации оценщиков, который рассматривает вопросы, отнесенные к его компетенции настоящим Федеральным законом и другими федеральными законами.\nОбщее собрание членов саморегулируемой организации оценщиков созывается не реже чем один раз в год в порядке, устанавливаемом уставом.\nК исключительной компетенции общего собрания членов саморегулируемой организации оценщиков относится решение следующих вопросов:\nутверждение положения о коллегиальном органе управления саморегулируемой организации оценщиков, образование коллегиального органа управления саморегулируемой организации оценщиков, принятие решений о досрочном прекращении полномочий коллегиального органа управления саморегулируемой организации оценщиков или о досрочном прекращении полномочий его членов;\nутверждение положения о раскрытии информации саморегулируемой организации оценщиков;\nутверждение положения о дисциплинарном комитете, образование дисциплинарного комитета, принятие решений о досрочном прекращении его полномочий или о досрочном прекращении полномочий его членов;\nутверждение внутренних документов саморегулируемой организации оценщиков, устанавливающих процедуру применения, а также иные меры дисциплинарного воздействия при несоблюдении членом саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, в соответствии с требованиями к рассмотрению жалоб; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 225-ФЗ) (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nутверждение в порядке и с периодичностью, которые установлены уставом, отчетов коллегиального органа управления саморегулируемой организации оценщиков и ее исполнительного органа о результатах финансово-хозяйственной и организационной деятельности саморегулируемой организации оценщиков;\nутверждение положения о членстве в саморегулируемой организации оценщиков;\nизбрание лица, сдавшего квалификационный экзамен, в состав экспертного совета саморегулируемой организации оценщиков или исключение лица из его состава; (Дополнение абзацем - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nпринятие решений о реорганизации, о добровольной ликвидации некоммерческой организации и назначении ликвидатора или ликвидационной комиссии. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\n(Особенности применения части - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)\nПорядок проведения общих собраний членов саморегулируемой организации оценщиков, порядок формирования повестки дня заседаний, определения кворума, условия и порядок проведения голосования определяются саморегулируемой организацией оценщиков самостоятельно в уставе.\nКоллегиальный орган управления саморегулируемой организации оценщиков образуется в составе не менее чем семь человек.\nК исключительной компетенции коллегиального органа управления саморегулируемой организации оценщиков относятся:\nутверждение стандартов и правил оценочной деятельности;\nутверждение правил деловой и профессиональной этики в соответствии с типовыми правилами профессиональной этики оценщиков;\nпринятие в члены саморегулируемой организации оценщиков, прекращение членства в саморегулируемой организации оценщиков;\nрассмотрение и утверждение рекомендации об исключении члена из саморегулируемой организации оценщиков или отклонение указанной рекомендации;\nприостановление права осуществления оценочной деятельности по заявлению члена саморегулируемой организации оценщиков, восстановление этого права;\nрассмотрение и утверждение рекомендации о приостановлении деятельности эксперта саморегулируемой организации оценщиков или отклонение указанной рекомендации и восстановление этой деятельности;\nобразование комитетов, предусмотренных внутренними документами саморегулируемой организации оценщиков, принятие решений о досрочном прекращении полномочий таких комитетов или о досрочном прекращении полномочий их членов, утверждение положений о структурном подразделении, осуществляющем контроль за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, и утверждение положений об иных комитетах;\nутверждение инвестиционной декларации компенсационного фонда;\nутверждение положения о порядке осуществления контроля за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики;\nустановление дополнительных требований к членам экспертного совета саморегулируемой организации оценщиков;\nустановление порядка утверждения экспертного заключения, подготовленного экспертом или экспертами саморегулируемой организации оценщиков;\nутверждение размера платы за проведение экспертизы отчетов;\nиные отнесенные уставом к исключительной компетенции коллегиального органа управления саморегулируемой организации оценщиков вопросы.\n(Часть в редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Особенности применения части - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)\nНе более чем двадцать пять процентов членов коллегиального органа управления саморегулируемой организации оценщиков должны составлять лица, не являющиеся членами саморегулируемой организации оценщиков и (или) их аффилированными лицами.\nЗаседания коллегиального органа управления саморегулируемой организации оценщиков могут проводиться в форме заочного голосования. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ)\nЧлены коллегиального органа управления саморегулируемой организации оценщиков не могут быть избраны в состав дисциплинарного комитета.\nЛицо, осуществляющее функции единоличного исполнительного органа саморегулируемой организации оценщиков, лица, являющиеся членами коллегиального исполнительного органа управления саморегулируемой организации оценщиков, не вправе:\nучреждать юридические лица или являться членами органов управления юридических лиц, осуществляющих оценочную деятельность, их дочерних и зависимых обществ;\nзаключать трудовые договоры с юридическими лицами, заключившими трудовые договоры с членами саморегулируемой организации оценщиков, а также с их дочерними и зависимыми обществами;\nзаключать гражданско-правовые договоры, в том числе договоры о возмездном оказании услуг, заказчиком по которым выступает член саморегулируемой организации оценщиков.\nДля обеспечения своей деятельности саморегулируемая организация оценщиков формирует:\nструктурное подразделение, осуществляющее контроль за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики; (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nдисциплинарный комитет; (В редакции федеральных законов от 24.07.2007 № 220-ФЗ; от 02.06.2016 № 172-ФЗ)\nиные определенные внутренними документами саморегулируемой организации оценщиков органы и структурные подразделения.\nЧасть. (Дополнение частью - Федеральный закон от 24.07.2007 № 220-ФЗ) (Утратила силу - Федеральный закон от 28.12.2010 № 431-ФЗ)\nУтверждение положения об экспертном совете саморегулируемой организации оценщиков и требований к членам экспертного совета саморегулируемой организации оценщиков, образование экспертного совета саморегулируемой организации оценщиков, принятие решений о досрочном прекращении его полномочий или полномочий его членов относятся к исключительной компетенции общего собрания членов саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 24.07.2007 № 220-ФЗ) (В редакции Федерального закона от 28.12.2010 № 431-ФЗ)\nЭкспертный совет саморегулируемой организации оценщиков образуется из членов саморегулируемой организации в случае его формирования. (Дополнение частью - Федеральный закон от 24.07.2007 № 220-ФЗ) (В редакции федеральных законов от 28.12.2010 № 431-ФЗ; от 02.06.2016 № 172-ФЗ)\nДисциплинарный комитет саморегулируемой организации оценщиков образуется в составе не менее трех членов саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ) (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.3","Порядок проведения саморегулируемой организацией оценщиков контроля за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 24.3. Порядок проведения саморегулируемой организацией оценщиков контроля за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики\nКонтроль за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики проводится соответствующим структурным подразделением саморегулируемой организации, состоящим из работников саморегулируемой организации оценщиков, имеющих высшее образование и сдавших квалификационный экзамен, путем проведения плановых и внеплановых проверок. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\n(Особенности применения части - Федеральный закон от 18.03.2020 № 66-ФЗ)\nПоложение о порядке осуществления контроля за деятельностью членов саморегулируемой организации оценщиков утверждается коллегиальным органом управления саморегулируемой организации оценщиков. Указанное положение должно определять порядок проведения плановых и внеплановых проверок членов саморегулируемой организации оценщиков, порядок взаимодействия структурного подразделения, осуществляющего контроль за соблюдением членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, с членами саморегулируемой организации оценщиков и другими структурными подразделениями саморегулируемой организации оценщиков, порядок оформления результатов таких проверок.\nЕжегодный план проведения проверок членов саморегулируемой организации оценщиков утверждается коллегиальным органом управления саморегулируемой организации оценщиков и доводится до сведения заинтересованных лиц посредством размещения указанного плана на официальном сайте саморегулируемой организации оценщиков в информационно-телекоммуникационной сети \"Интернет\" не позднее 15 декабря года, предшествующего году проведения плановых проверок.\nПредметом плановой проверки является соблюдение членами саморегулируемой организации оценщиков требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, дополнительных требований к порядку обеспечения имущественной ответственности своих членов. Продолжительность плановой проверки не должна превышать тридцать дней.\nОснованием для проведения саморегулируемой организацией оценщиков внеплановой проверки является поступившая в саморегулируемую организацию оценщиков жалоба, содержащая доводы заявителя относительно того, как действия (бездействие) члена саморегулируемой организации оценщиков нарушают или могут нарушить права заявителя.\nВнутренними документами саморегулируемой организации оценщиков могут быть предусмотрены и иные основания для проведения внеплановой проверки.\nЧлен саморегулируемой организации оценщиков обязан представить для проведения проверки необходимые документы и информацию по запросу саморегулируемой организации оценщиков в порядке, установленном внутренними документами саморегулируемой организации оценщиков.\nО принятии жалобы к рассмотрению и начале проведения внеплановой проверки или об отказе от проведения внеплановой проверки с указанием причин такого отказа саморегулируемая организация оценщиков уведомляет лицо, направившее жалобу, в течение десяти дней с момента получения жалобы саморегулируемой организацией оценщиков. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nПо результатам проведенной проверки составляется акт проверки в соответствии с требованиями к рассмотрению жалоб.\nЧасть. (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nВ случае выявления нарушения акт проверки и материалы проверки передаются в дисциплинарный комитет в течение трех рабочих дней с даты составления акта проверки.\nЧасть. (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nО результатах проверки саморегулируемая организация оценщиков сообщает члену саморегулируемой организации оценщиков и лицу, направившему жалобу, в течение трех рабочих дней с даты составления акта проверки любым доступным способом, обеспечивающим подтверждение такого сообщения.\nОбщий срок рассмотрения жалобы с даты ее поступления в саморегулируемую организацию оценщиков до даты принятия решения дисциплинарным комитетом не может превышать шестьдесят дней.\nРезультаты рассмотрения жалобы и (или) решения дисциплинарного комитета могут быть обжалованы заинтересованными лицами в саморегулируемую организацию оценщиков в порядке и в сроки, которые предусмотрены требованиями к рассмотрению жалоб, или оспорены в судебном порядке. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["24.4","Порядок применения мер дисциплинарного воздействия в отношении членов саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 24.4. Порядок применения мер дисциплинарного воздействия в отношении членов саморегулируемой организации оценщиков\nДисциплинарный комитет обязан рассматривать жалобы и сформированные по итогам проведения проверок членов саморегулируемой организации оценщиков дела о нарушении ее членами требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, требований о внесении обязательных взносов в саморегулируемую организацию оценщиков и дополнительных требований к порядку обеспечения имущественной ответственности своих членов и о применении в отношении ее членов мер дисциплинарного воздействия (далее - дела о применении мер дисциплинарного воздействия).\nПроцедура рассмотрения жалоб и дел о применении мер дисциплинарного воздействия, содержание указанных нарушений определяются внутренними документами саморегулируемой организации оценщиков, которые должны отвечать требованиям к рассмотрению жалоб.\nПри рассмотрении жалоб и дел о применении мер дисциплинарного воздействия дисциплинарный комитет обязан приглашать на свои заседания с указанием даты, места и времени их проведения лиц, направивших жалобы, по результатам рассмотрения которых формируются дела о применении мер дисциплинарного воздействия, а также членов саморегулируемой организации оценщиков, в отношении которых рассматриваются дела о применении мер дисциплинарного воздействия. Уведомление указанных лиц осуществляется любым доступным способом, обеспечивающим возможность подтверждения факта уведомления, не позднее чем за десять дней до дня заседания дисциплинарного комитета. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nДисциплинарный комитет вправе принять решение о применении следующих мер дисциплинарного воздействия:\nвынесение предписания, обязывающего члена саморегулируемой организации оценщиков устранить выявленные в результате проведенной проверки нарушения и устанавливающего сроки их устранения;\nвынесение члену саморегулируемой организации оценщиков предупреждения;\nналожение на члена саморегулируемой организации оценщиков штрафа в размере, установленном внутренними документами саморегулируемой организации оценщиков;\nприостановление права осуществления оценочной деятельности; (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nрекомендация о приостановлении деятельности эксперта саморегулируемой организации оценщиков, подлежащая рассмотрению и утверждению или отклонению коллегиальным органом управления саморегулируемой организации оценщиков;\nрекомендация об исключении члена саморегулируемой организации оценщиков из состава экспертного совета саморегулируемой организации оценщиков, подлежащая рассмотрению и утверждению или отклонению общим собранием членов саморегулируемой организации оценщиков;\nрекомендация об исключении из членов саморегулируемой организации оценщиков, подлежащая рассмотрению и утверждению или отклонению коллегиальным органом управления саморегулируемой организации оценщиков;\nиные установленные внутренними документами саморегулируемой организации оценщиков меры дисциплинарного воздействия.\nОснованием для принятия дисциплинарным комитетом решения о применении меры дисциплинарного воздействия в виде приостановления права осуществления оценочной деятельности является:\nнеоднократное в течение двух месяцев нарушение членом саморегулируемой организации оценщиков требований настоящего Федерального закона, а также внутренних документов саморегулируемой организации оценщиков о представлении в саморегулируемую организацию оценщиков информации и документов, необходимых для проведения плановой или внеплановой проверки;\nнепредставление в саморегулируемую организацию оценщиков действующего договора обязательного страхования ответственности оценщика;\nприменение повторно в течение одного года в отношении члена саморегулируемой организации оценщиков меры дисциплинарного воздействия с даты применения впервые меры дисциплинарного воздействия за нарушение им требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, требований о внесении обязательных взносов в саморегулируемую организацию оценщиков и дополнительных требований к порядку обеспечения имущественной ответственности членов саморегулируемой организации оценщиков;\nвыявление факта несоответствия члена саморегулируемой организации оценщиков обязательному условию членства в саморегулируемой организации оценщиков, установленному абзацем четвертым части второй статьи 24 настоящего Федерального закона; (Дополнение абзацем - Федеральный закон от 18.03.2020 № 66-ФЗ)\nиные основания, предусмотренные внутренними документами саморегулируемой организации оценщиков.\n(Часть в редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nОснованием для принятия дисциплинарным комитетом решения о применении меры дисциплинарного воздействия в виде рекомендации об исключении из членов саморегулируемой организации оценщиков является:\nневыполнение предписания, обязывающего члена саморегулируемой организации оценщиков устранить выявленные нарушения в установленные сроки после применения меры дисциплинарного воздействия, повлекшей за собой приостановление права осуществления оценочной деятельности;\nвыявление факта представления для приема в члены саморегулируемой организации оценщиков подложных документов;\nосуществление оценочной деятельности в период приостановления права ее осуществления;\nосуществление оценочной деятельности без наличия действующего договора обязательного страхования ответственности;\nпроведение экспертизы отчетов в период приостановления деятельности эксперта саморегулируемой организации оценщиков;\nнесоблюдение членом саморегулируемой организации оценщиков требований статьи 16 настоящего Федерального закона в части независимости оценщика;\nприменение более двух раз в течение одного года в отношении члена саморегулируемой организации оценщиков мер дисциплинарного воздействия за нарушение им требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности, правил деловой и профессиональной этики, требований о внесении обязательных взносов в саморегулируемую организацию оценщиков и дополнительных требований к порядку обеспечения имущественной ответственности членов саморегулируемой организации оценщиков;\nнеустранение членом саморегулируемой организации оценщиков факта несоответствия обязательному условию членства в саморегулируемой организации оценщиков, установленному абзацем четвертым части второй статьи 24 настоящего Федерального закона, в течение трех месяцев с даты выявления такого факта. (Дополнение абзацем - Федеральный закон от 18.03.2020 № 66-ФЗ)\n(Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nРешения, предусмотренные абзацами вторым - пятым и девятым части четвертой настоящей статьи, вступают в силу с момента их принятия дисциплинарным комитетом. Решение, предусмотренное абзацем седьмым части четвертой настоящей статьи, может быть принято не менее чем семьюдесятью пятью процентами голосов членов дисциплинарного комитета, присутствующих на его заседании, и вступает в силу с момента его утверждения общим собранием членов саморегулируемой организации оценщиков. Решение, предусмотренное абзацами шестым и восьмым части четвертой настоящей статьи, может быть принято не менее чем семьюдесятью пятью процентами голосов членов дисциплинарного комитета, присутствующих на его заседании, и вступает в силу с момента его утверждения коллегиальным органом управления саморегулируемой организации оценщиков. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nВ течение двух рабочих дней со дня принятия дисциплинарным комитетом решения о применении меры дисциплинарного воздействия к члену саморегулируемой организации оценщиков саморегулируемая организация оценщиков направляет копии такого решения члену саморегулируемой организации оценщиков и лицу, направившему жалобу, по которой принято такое решение.\nРешения дисциплинарного комитета могут быть обжалованы членами саморегулируемой организации оценщиков в коллегиальный орган управления саморегулируемой организации оценщиков в сроки, установленные требованиями к рассмотрению жалоб.\nРешение общего собрания членов саморегулируемой организации оценщиков об утверждении или отклонении рекомендации дисциплинарного комитета об исключении члена саморегулируемой организации оценщиков из состава экспертного совета саморегулируемой организации оценщиков может быть оспорено заинтересованными лицами в арбитражном суде.\nРешения коллегиального органа управления саморегулируемой организации оценщиков об утверждении или отклонении рекомендации дисциплинарного комитета об исключении лица из членов саморегулируемой организации оценщиков, о приостановлении права осуществления оценочной деятельности, о приостановлении деятельности эксперта саморегулируемой организации оценщиков могут быть оспорены заинтересованными лицами в арбитражном суде.\nДенежные средства, полученные саморегулируемой организацией оценщиков в результате наложения на члена саморегулируемой организации оценщиков штрафа в соответствии с настоящей статьей, подлежат зачислению в компенсационный фонд саморегулируемой организации оценщиков.\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["24.5","Надзор за деятельностью саморегулируемых организаций оценщиков и ведение сводного реестра членов саморегулируемых организаций оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2021-06-11","Статья 24.5. Надзор за деятельностью саморегулируемых организаций оценщиков и ведение сводного реестра членов саморегулируемых организаций оценщиков\n(Наименование в редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nНадзор за деятельностью саморегулируемых организаций оценщиков осуществляется путем проведения плановых и внеплановых проверок уполномоченным федеральным органом, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков. Порядок осуществления надзора за деятельностью саморегулируемых организаций оценщиков устанавливается уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (В редакции Федерального закона от 22.07.2010 № 167-ФЗ)\nК отношениям, связанным с осуществлением федерального государственного надзора за деятельностью саморегулируемых организаций оценщиков, применяются положения Федерального закона от 26 декабря 2008 года № 294-ФЗ \"О защите прав юридических лиц и индивидуальных предпринимателей при осуществлении государственного контроля (надзора) и муниципального контроля\" с учетом особенностей организации и проведения плановых и внеплановых проверок, установленных Федеральным законом от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\" и настоящим Федеральным законом. (В редакции Федерального закона от 11.06.2021 № 170-ФЗ)\nОснованиями для проведения внеплановой проверки деятельности саморегулируемой организации оценщиков являются:\nпредставленные в уполномоченный федеральный орган, осуществляющий функции по федеральному государственному надзору за деятельностью саморегулируемых организаций оценщиков (далее - орган государственного надзора), заявления юридических лиц, физических лиц, федеральных органов государственной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, правоохранительных органов о нарушении саморегулируемой организацией оценщиков настоящего Федерального закона, других федеральных законов и иных нормативных правовых актов Российской Федерации;\nимеющиеся в документах саморегулируемой организации оценщиков, представленных в орган государственного надзора, несоответствия требованиям настоящего Федерального закона, других федеральных законов и иных нормативных правовых актов Российской Федерации;\nмотивированное представление должностного лица органа государственного надзора по результатам анализа результатов мероприятий по контролю без взаимодействия с саморегулируемыми организациями оценщиков;\nнепредставление саморегулируемой организацией оценщиков в орган государственного надзора документов и сведений об исполнении предписания об устранении выявленных нарушений в срок, установленный таким предписанием, либо представление саморегулируемой организацией оценщиков в орган государственного надзора документов и сведений об исполнении предписания об устранении выявленного нарушения, на основании которых невозможно сделать вывод об исполнении такого предписания.\n(Часть в редакции Федерального закона от 11.06.2021 № 170-ФЗ)\nВ ходе проведения проверки деятельности саморегулируемой организации оценщиков уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, вправе запрашивать у специализированного депозитария, заключившего депозитарный договор с саморегулируемой организацией оценщиков, информацию о денежной оценке ее компенсационного фонда.\nО своем решении, принятом на основании материалов проведения проверки, уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, извещает саморегулируемую организацию оценщиков в письменной форме в срок не позднее трех дней со дня принятия такого решения.\nВ случае выявления нарушения требований, установленных частью третьей статьи 22 настоящего Федерального закона, уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, обращается в арбитражный суд с заявлением об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков.\nВ случае выявления иных нарушений уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, направляет в саморегулируемую организацию оценщиков предписание об устранении в разумные сроки выявленных нарушений.\nПредписание уполномоченного федерального органа, осуществляющего функции по надзору за деятельностью саморегулируемых организаций оценщиков, об устранении выявленных нарушений может быть обжаловано саморегулируемой организацией оценщиков в арбитражный суд.\nВ случае невыполнения в установленный срок предписания об устранении выявленных нарушений уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, обращается в арбитражный суд с заявлением об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков.\nСаморегулируемая организация оценщиков, выявившая свое несоответствие требованиям части третьей статьи 22 настоящего Федерального закона, вправе направить в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, в письменной форме заявление о выявленном несоответствии с его описанием, указанием сведений о дате его возникновения и о принимаемых и (или) планируемых саморегулируемой организацией оценщиков мерах по его устранению.\nВ течение двух месяцев после получения уполномоченным федеральным органом, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, заявления о выявленном несоответствии саморегулируемая организация оценщиков не может быть исключена из единого государственного реестра саморегулируемых организаций оценщиков по указанному в заявлении основанию. В случае, если по истечении указанного срока саморегулируемая организация оценщиков не представит в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, доказательство устранения выявленного несоответствия, уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, обращается в арбитражный суд с заявлением об исключении саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков.\nСаморегулируемая организация оценщиков считается исключенной из единого государственного реестра саморегулируемых организаций оценщиков с даты вступления в силу решения арбитражного суда о ее исключении из указанного реестра.\nОценщики, состоявшие членами саморегулируемой организации оценщиков, исключенной из единого государственного реестра саморегулируемых организаций оценщиков, вправе вступить в иные саморегулируемые организации оценщиков.\nВ течение трех месяцев с даты исключения саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков оценщики, состоявшие ее членами и не вступившие в другие саморегулируемые организации оценщиков, вправе осуществлять оценочную деятельность только по договорам, заключенным до даты исключения саморегулируемой организации оценщиков из единого государственного реестра саморегулируемых организаций оценщиков.\nУполномоченный федеральный орган исполнительной власти, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, осуществляет формирование и ведение сводного реестра членов саморегулируемых организаций оценщиков. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\nПеречень сведений, включаемых в сводный реестр членов саморегулируемых организаций оценщиков, порядок формирования и ведения сводного реестра членов саморегулируемых организаций оценщиков и порядок опубликования сводного реестра членов саморегулируемых организаций оценщиков устанавливаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (Дополнение частью - Федеральный закон от 21.07.2014 № 225-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.6","Обеспечение имущественной ответственности при осуществлении оценочной деятельности","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2018-11-28","Статья 24.6. Обеспечение имущественной ответственности при осуществлении оценочной деятельности\nУбытки, причиненные заказчику, заключившему договор на проведение оценки, или имущественный вред, причиненный третьим лицам вследствие использования итоговой величины рыночной или иной стоимости объекта оценки, указанной в отчете, подписанном оценщиком или оценщиками, подлежат возмещению в полном объеме за счет имущества оценщика или оценщиков, причинивших своими действиями (бездействием) убытки или имущественный вред при осуществлении оценочной деятельности, или за счет имущества юридического лица, с которым оценщик заключил трудовой договор.\nУбытки, причиненные заказчику, заключившему договор на проведение оценки, также подлежат возмещению в полном объеме за счет страховых выплат по договору страхования ответственности юридического лица, с которым оценщик заключил трудовой договор, за нарушение договора на проведение оценки и причинение вреда имуществу третьих лиц в результате нарушения требований настоящего Федерального закона, федеральных стандартов оценки, иных нормативных правовых актов Российской Федерации в области оценочной деятельности, стандартов и правил оценочной деятельности. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nВ целях обеспечения имущественной ответственности членов саморегулируемой организации оценщиков перед заключившим договор на проведение оценки заказчиком и (или) третьими лицами саморегулируемая организация оценщиков обязана предъявлять к своим членам требования об использовании следующих видов обеспечения такой ответственности:\nзаключение предусмотренного статьей 24.7 настоящего Федерального закона договора обязательного страхования ответственности оценщика при осуществлении оценочной деятельности, размер страховой суммы в котором не может быть менее чем триста тысяч рублей;\nформирование компенсационного фонда саморегулируемой организации оценщиков, в который каждым членом саморегулируемой организации оценщиков должен быть внесен обязательный взнос в размере не менее чем тридцать тысяч рублей.\n(Особенности применения части - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)\nСаморегулируемая организация оценщиков, экспертом или экспертами которой подготовлено и утверждено в порядке, установленном внутренними документами саморегулируемой организации оценщиков, положительное экспертное заключение, несет солидарную ответственность за убытки, причиненные заказчику, заключившему договор на проведение оценки, или имущественный вред, причиненный третьим лицам действиями (бездействием) оценщика или оценщиков вследствие установленного судом, арбитражным судом в соответствии с установленной компетенцией, третейским судом нарушения требований федеральных стандартов оценки, стандартов и правил оценочной деятельности. Саморегулируемая организация оценщиков, возместившая убытки или имущественный вред, имеет право регресса к эксперту или экспертам саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n(Особенности применения части - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)\nВозмещение заказчику оценки и (или) третьему лицу убытков или имущественного вреда, которые возникают в случаях, предусмотренных настоящей статьей, и установлены вступившим в законную силу решением суда, арбитражного суда в соответствии с установленной компетенцией, третейского суда, производится за счет средств компенсационного фонда саморегулируемой организации оценщиков, членами которой являются эксперт или эксперты, в размере не более чем пять миллионов рублей. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции федеральных законов от 21.07.2014 № 225-ФЗ; от 28.11.2018 № 451-ФЗ)\n(Особенности применения части - федеральные законы от 28.12.2010 № 431-ФЗ, от 28.07.2012 № 144-ФЗ)\nСаморегулируемая организация оценщиков вправе устанавливать дополнительные требования к имущественной ответственности экспертов саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.7","Договор обязательного страхования ответственности оценщика при осуществлении оценочной деятельности","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 24.7. Договор обязательного страхования ответственности оценщика при осуществлении оценочной деятельности\nОбъектом страхования по договору обязательного страхования ответственности оценщика при осуществлении оценочной деятельности (далее - договор обязательного страхования ответственности) являются имущественные интересы, связанные с риском ответственности оценщика (страхователя) по обязательствам, возникающим вследствие причинения ущерба заказчику, заключившему договор на проведение оценки, и (или) третьим лицам.\nСтраховым случаем по договору обязательного страхования ответственности является установленный вступившим в законную силу решением арбитражного суда или признанный страховщиком факт причинения ущерба действиями (бездействием) оценщика в результате нарушения требований федеральных стандартов оценки, стандартов и правил оценочной деятельности, установленных саморегулируемой организацией оценщиков, членом которой являлся оценщик на момент причинения ущерба.\nВ случае наступления страхового случая страховщик производит страховую выплату в размере причиненного заказчику и (или) третьему лицу реального ущерба, установленном вступившим в законную силу решением арбитражного суда, но не более чем в размере страховой суммы по договору обязательного страхования ответственности.\nДоговор обязательного страхования ответственности заключается членом саморегулируемой организации оценщиков на срок не менее одного года с условием возмещения ущерба, причиненного в период действия договора обязательного страхования ответственности, в течение срока исковой давности, установленного законодательством Российской Федерации. (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nЧлен саморегулируемой организации оценщиков вправе не страховать ответственность оценщика на период приостановления права осуществления им оценочной деятельности. (Дополнение частью - Федеральный закон от 02.06.2016 № 172-ФЗ)\nСтраховой тариф по договору обязательного страхования ответственности может определяться страховщиками в зависимости от стажа осуществления оценочной деятельности оценщиком, количества предыдущих страховых случаев и иных влияющих на степень риска причинения ущерба обстоятельств.\nДоговор обязательного страхования ответственности может предусматривать уплату оценщиком страховой премии в рассрочку и сроки уплаты страховых взносов.\nДатой уплаты страховой премии (страхового взноса) считается день уплаты страховой премии (страхового взноса) наличными деньгами страховщику или день перечисления страховой премии (страхового взноса) на расчетный счет страховщика.\nДоговор обязательного страхования ответственности вступает в силу с момента уплаты страхователем первого страхового взноса, если законодательством Российской Федерации не предусмотрено иное.\nКонтроль за осуществлением своими членами обязательного страхования ответственности проводится саморегулируемой организацией оценщиков, которая вправе устанавливать дополнительные не противоречащие законодательству Российской Федерации требования к договорам обязательного страхования ответственности, заключаемым членами такой саморегулируемой организации оценщиков.\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.8","Компенсационный фонд саморегулируемой организации оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2020-03-18","Статья 24.8. Компенсационный фонд саморегулируемой организации оценщиков\nКомпенсационным фондом саморегулируемой организации оценщиков (далее - компенсационный фонд) является обособленное имущество, принадлежащее саморегулируемой организации оценщиков на праве собственности и первоначально формируемое исключительно в денежной форме за счет обязательных взносов ее членов.\nНе допускается освобождение члена саморегулируемой организации оценщиков от обязанности внесения взносов в компенсационный фонд, в том числе зачет его требований к саморегулируемой организации оценщиков, за исключением случая формирования компенсационного фонда при реорганизации саморегулируемой организации оценщиков в форме присоединения. При реорганизации саморегулируемой организации оценщиков член присоединенной саморегулируемой организации оценщиков считается внесшим взнос в компенсационный фонд реорганизованной саморегулируемой организации оценщиков. (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nОснованием для обращения взыскания на компенсационный фонд считается установленный решением арбитражного суда или признанный страховщиком факт наступления страхового случая по договору обязательного страхования ответственности.\nТребование о получении компенсационной выплаты за счет компенсационного фонда может быть предъявлено к саморегулируемой организации оценщиков, национальному объединению саморегулируемых организаций оценщиков в случае передачи ему имущества, составляющего компенсационный фонд саморегулируемой организации оценщиков, только в случае совпадения следующих условий: (В редакции федеральных законов от 28.12.2010 № 431-ФЗ; от 21.07.2014 № 225-ФЗ)\nдля возмещения ущерба, причиненного оценщиком, недостаточно средств, полученных по договору обязательного страхования ответственности;\nоценщик отказался удовлетворить требование заказчика или третьего лица о возмещении ущерба либо заказчик или третье лицо не получили от него в разумный срок ответ на предъявленное требование.\nТребование о возмещении ущерба за счет компенсационного фонда может быть предъявлено к саморегулируемой организации оценщиков, членом которой является или являлся оценщик на момент причинения ущерба, национальному объединению саморегулируемых организаций оценщиков в случае передачи ему имущества, составляющего компенсационный фонд саморегулируемой организации оценщиков, членом которой являлся оценщик на момент причинения ущерба. (В редакции федеральных законов от 28.12.2010 № 431-ФЗ; от 21.07.2014 № 225-ФЗ)\nНе допускается осуществление выплат за счет компенсационного фонда (в том числе возврат членам саморегулируемой организации оценщиков их взносов), за исключением выплат, предусмотренных настоящим Федеральным законом. (В редакции Федерального закона от 28.12.2010 № 431-ФЗ)\nНа компенсационный фонд не может быть обращено взыскание по обязательствам саморегулируемой организации оценщиков, а также по обязательствам членов саморегулируемой организации оценщиков, если возникновение таких обязательств не связано с осуществлением регулируемого ею вида деятельности.\nРазмер компенсационной выплаты за счет компенсационного фонда по требованию или требованиям заказчиков либо третьих лиц к одному оценщику по одному страховому случаю не может превышать пяти миллионов рублей. (В редакции Федерального закона от 28.12.2010 № 431-ФЗ)\nВ случае ликвидации некоммерческой организации, имеющей статус саморегулируемой организации оценщиков, и (или) исключения сведений о некоммерческой организации из единого государственного реестра саморегулируемых организаций оценщиков, кроме случаев исключения сведений о некоммерческой организации из единого государственного реестра саморегулируемых организаций оценщиков в связи с ее реорганизацией, имущество, составляющее компенсационный фонд такой некоммерческой организации, подлежит передаче национальному объединению саморегулируемых организаций оценщиков (при его наличии). (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции федеральных законов от 21.07.2014 № 225-ФЗ, от 18.03.2020 № 66-ФЗ)\nК порядку размещения средств компенсационного фонда саморегулируемой организации оценщиков, переданных национальному объединению саморегулируемых организаций оценщиков, предъявляются требования, аналогичные требованиям, предъявляемым к порядку размещения средств компенсационного фонда саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nИмущество, составляющее компенсационный фонд саморегулируемой организации оценщиков и переданное национальному объединению саморегулируемых организаций оценщиков, по истечении четырех лет с даты ликвидации саморегулируемой организации оценщиков и (или) исключения сведений о некоммерческой организации из единого государственного реестра саморегулируемых организаций оценщиков подлежит возврату в денежной форме лицам, являвшимся членами такой саморегулируемой организации, в размере, не превышающем размера их взносов в компенсационный фонд саморегулируемой организации оценщиков, в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (Дополнение частью - Федеральный закон от 28.12.2010 № 431-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)\nВ случае отсутствия национального объединения саморегулируемых организаций оценщиков при ликвидации некоммерческой организации, имеющей статус саморегулируемой организации оценщиков, и (или) исключения сведений о некоммерческой организации из единого государственного реестра саморегулируемых организаций оценщиков, кроме случаев исключения сведений о некоммерческой организации из единого государственного реестра саморегулируемых организаций оценщиков в связи с ее реорганизацией, имущество, составляющее компенсационный фонд такой некоммерческой организации, подлежит внесению в депозит нотариуса. (Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\nИмущество, составляющее компенсационный фонд саморегулируемой организации оценщиков, вносится в депозит нотариуса в денежной форме. (Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\nОбращение взыскания на компенсационный фонд саморегулируемой организации оценщиков, внесенный в депозит нотариуса, осуществляется в соответствии с настоящей статьей. (Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\nВ случае реорганизации саморегулируемой организации оценщиков компенсационный фонд реорганизованной саморегулируемой организации оценщиков формируется в том числе за счет компенсационного фонда присоединенной саморегулируемой организации оценщиков. (Дополнение частью - Федеральный закон от 18.03.2020 № 66-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.9","Условия и порядок размещения средств компенсационного фонда","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2016-06-02","Статья 24.9. Условия и порядок размещения средств компенсационного фонда\nСаморегулируемая организация оценщиков для размещения средств компенсационного фонда в целях их сохранения и увеличения заключает с управляющей компанией договор доверительного управления таким фондом.\nУправляющая компания обязана совершить все необходимые действия по недопущению нарушения установленных настоящим Федеральным законом требований к размещению средств компенсационного фонда и заключить договор со специализированным депозитарием, с которым заключен договор саморегулируемой организацией оценщиков.\nСпециализированный депозитарий осуществляет контроль за соблюдением управляющей компанией ограничений размещения средств компенсационного фонда, правил размещения этих средств и требований к их размещению, установленных настоящим Федеральным законом и инвестиционной декларацией, принятой саморегулируемой организацией оценщиков.\nОбо всех случаях нарушения установленных настоящим Федеральным законом требований к размещению средств компенсационного фонда специализированный депозитарий уведомляет саморегулируемую организацию оценщиков и уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков.\nУправляющая компания и специализированный депозитарий отбираются по результатам конкурса, проведенного в порядке, установленном внутренними документами саморегулируемой организации оценщиков.\nДоход, полученный от размещения средств компенсационного фонда, направляется на пополнение этого фонда и покрытие расходов, связанных с обеспечением надлежащих условий размещения таких средств.\nСредства компенсационного фонда размещаются управляющей компанией в соответствии с инвестиционной декларацией, принятой саморегулируемой организацией оценщиков, и с учетом ограничений, установленных настоящей статьей. Не более чем сорок процентов этих средств должно быть размещено в государственные ценные бумаги Российской Федерации, и не более чем сорок процентов этих средств может быть размещено в обращающиеся на организованных торгах акции российских эмитентов, созданных в форме открытых акционерных обществ, или паи паевых инвестиционных фондов. (В редакции федеральных законов от 21.11.2011 № 327-ФЗ; от 02.06.2016 № 172-ФЗ)\nНе допускается размещать более чем пять процентов средств компенсационного фонда в акции одного эмитента, а также размещать средства компенсационного фонда в векселя, ценные бумаги, не обращающиеся на организованных торгах, и иностранные ценные бумаги. (В редакции Федерального закона от 21.11.2011 № 327-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ)"],
["24.10","Национальное объединение саморегулируемых организаций оценщиков и иные объединения саморегулируемых организаций оценщиков","ГЛАВА III. РЕГУЛИРОВАНИЕ ОЦЕНОЧНОЙ ДЕЯТЕЛЬНОСТИ","2025-07-31","Статья 24.10. Национальное объединение саморегулируемых организаций оценщиков и иные объединения саморегулируемых организаций оценщиков\nВ целях обеспечения общественных интересов, формирования единых подходов к осуществлению оценочной деятельности, выработки единой позиции оценщиков по вопросам регулирования их деятельности, координации деятельности саморегулируемых организаций оценщиков, а также в целях взаимодействия саморегулируемых организаций оценщиков с федеральными органами государственной власти, органами государственной власти субъектов Российской Федерации, органами местного самоуправления и потребителями услуг в области оценочной деятельности саморегулируемые организации оценщиков вправе создать национальное объединение саморегулируемых организаций оценщиков и иные объединения саморегулируемых организаций оценщиков с соблюдением требований настоящего Федерального закона, Федерального закона от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\" и принятых в соответствии с ними иных нормативных правовых актов Российской Федерации.\nНациональным объединением саморегулируемых организаций оценщиков признается некоммерческая организация, которая создана саморегулируемыми организациями оценщиков, зарегистрирована уполномоченным федеральным органом исполнительной власти, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, и членами которой являются более чем семьдесят пять процентов саморегулируемых организаций оценщиков, включенных в единый государственный реестр саморегулируемых организаций оценщиков и объединяющих более чем пятьдесят процентов оценщиков, включенных в сводный реестр членов саморегулируемых организаций оценщиков, право осуществления оценочной деятельности которых не приостановлено.\nНациональное объединение саморегулируемых организаций оценщиков не вправе отказать в приеме в свои члены саморегулируемой организации оценщиков.\nНациональное объединение саморегулируемых организаций оценщиков не вправе осуществлять предпринимательскую деятельность и иную приносящую доход деятельность.\nНекоммерческая организация, соответствующая требованиям части второй настоящей статьи, подлежит регистрации в едином государственном реестре саморегулируемых организаций оценщиков в качестве национального объединения саморегулируемых организаций оценщиков по истечении трех рабочих дней с даты представления в уполномоченный федеральный орган исполнительной власти, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, с использованием информационно-телекоммуникационных сетей, в том числе информационно-телекоммуникационной сети \"Интернет\", включая единый портал государственных и муниципальных услуг, подписанных усиленной квалифицированной электронной подписью в соответствии с требованиями Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\" или подписанных физическим лицом, действующим от имени некоммерческой организации на основании доверенности в электронной форме в машиночитаемом виде, усиленной квалифицированной электронной подписью или усиленной неквалифицированной электронной подписью, сертификат ключа проверки которой создан и используется в инфраструктуре, обеспечивающей информационно-технологическое взаимодействие информационных систем, используемых для предоставления государственных и муниципальных услуг в электронной форме, в установленном Правительством Российской Федерации порядке и при условии организации взаимодействия физического лица с такой инфраструктурой с применением прошедших в установленном порядке процедуру оценки соответствия средств защиты информации, следующих документов: (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nзаявление о регистрации в качестве национального объединения саморегулируемых организаций оценщиков с указанием наименования некоммерческой организации, основного государственного регистрационного номера, идентификационного номера налогоплательщика, адреса официального сайта некоммерческой организации в информационно-телекоммуникационной сети \"Интернет\", адреса электронной почты; (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 31.07.2025 № 304-ФЗ)\nкопии заявлений о вступлении в некоммерческую организацию всех ее членов. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nОсновными функциями национального объединения саморегулируемых организаций оценщиков являются:\nобсуждение вопросов государственной политики в области оценочной деятельности;\nпредставление интересов саморегулируемых организаций оценщиков в федеральных органах государственной власти, органах государственной власти субъектов Российской Федерации, органах местного самоуправления;\nформирование предложений по вопросам выработки государственной политики в области оценочной деятельности;\nформирование предложений о совершенствовании правового и экономического регулирования оценочной деятельности;\nзащита прав и законных интересов саморегулируемых организаций оценщиков;\nразработка федеральных стандартов оценки, за исключением федеральных стандартов оценки, устанавливающих требования к определению кадастровой стоимости;\nрассмотрение проектов нормативных правовых актов Российской Федерации в области оценочной деятельности и предоставление рекомендаций об их утверждении;\nразработка дополнительных образовательных программ в области оценочной деятельности;\nразработка рекомендаций о минимальном стаже оценщиков, сроке стажировки лиц, претендующих на членство в саморегулируемой организации оценщиков;\nрассмотрение обращений, ходатайств, жалоб на саморегулируемые организации оценщиков от потребителей услуг в области оценочной деятельности и оценщиков;\nразмещение средств компенсационного фонда, переданных национальному объединению саморегулируемых организаций оценщиков, в случае, установленном статьей 24.8 настоящего Федерального закона;\nвозврат имущества, составляющего компенсационный фонд и переданного национальному объединению саморегулируемых организаций оценщиков, в случае, установленном статьей 24.8 настоящего Федерального закона.\nВысшим органом управления национального объединения саморегулируемых организаций оценщиков является общее собрание членов национального объединения саморегулируемых организаций оценщиков.\nОбщее собрание членов национального объединения саморегулируемых организаций оценщиков созывается не реже чем один раз в год. Внеочередное общее собрание членов национального объединения саморегулируемых организаций оценщиков может быть созвано по инициативе не менее одной трети саморегулируемых организаций оценщиков.\nРешение общего собрания членов национального объединения саморегулируемых организаций оценщиков считается принятым, если за него проголосовали не менее чем две трети участников собрания и при этом в собрании участвовали не менее чем пятьдесят процентов общего числа членов национального объединения саморегулируемых организаций оценщиков.\nЧлены национального объединения саморегулируемых организаций оценщиков имеют равные права и равное представительство на общем собрании членов национального объединения саморегулируемых организаций оценщиков. Каждый член национального объединения саморегулируемых организаций оценщиков независимо от количества его представителей при принятии решений имеет один голос.\nК компетенции общего собрания членов национального объединения саморегулируемых организаций оценщиков относятся:\nизменение устава национального объединения саморегулируемых организаций оценщиков;\nопределение приоритетных направлений деятельности национального объединения саморегулируемых организаций оценщиков, принципов формирования и использования его имущества;\nобразование исполнительных органов национального объединения саморегулируемых организаций оценщиков и досрочное прекращение их полномочий;\nсоздание филиалов и открытие представительств национального объединения саморегулируемых организаций оценщиков;\nучастие в других организациях;\nреорганизация и ликвидация национального объединения саморегулируемых организаций оценщиков;\nформирование постоянно действующего коллегиального органа управления национального объединения саморегулируемых организаций оценщиков (далее - коллегиальный орган управления национального объединения саморегулируемых организаций оценщиков), в том числе избрание председателя коллегиального органа управления национального объединения саморегулируемых организаций оценщиков, членов коллегиального органа управления национального объединения саморегулируемых организаций оценщиков и прекращение полномочий членов коллегиального органа управления национального объединения саморегулируемых организаций оценщиков, принятие решений о досрочном прекращении полномочий членов коллегиального органа управления национального объединения саморегулируемых организаций оценщиков;\nутверждение положения о коллегиальном органе управления национального объединения саморегулируемых организаций оценщиков, устанавливающего также права и обязанности председателя и иных членов этого органа, функции коллегиального органа управления национального объединения саморегулируемых организаций оценщиков;\nутверждение положений о членстве, об общем собрании членов национального объединения саморегулируемых организаций оценщиков, исполнительном органе национального объединения саморегулируемых организаций оценщиков;\nутверждение размеров вступительного взноса, членских и иных взносов;\nутверждение инвестиционной декларации компенсационного фонда, переданного национальному объединению саморегулируемых организаций оценщиков, в случае, установленном статьей 24.8 настоящего Федерального закона;\nутверждение аудитора национального объединения саморегулируемых организаций оценщиков и размера оплаты его услуг;\nутверждение годового отчета национального объединения саморегулируемых организаций оценщиков, отчета исполнительного директора о результатах финансово-хозяйственной и организационной деятельности национального объединения саморегулируемых организаций оценщиков, бухгалтерской (финансовой) отчетности национального объединения саморегулируемых организаций оценщиков, сметы доходов и расходов национального объединения саморегулируемых организаций оценщиков;\nобразование иных органов национального объединения саморегулируемых организаций оценщиков и прекращение полномочий соответствующих органов или полномочий их членов, утверждение положений об этих органах, определение кадровой политики, в том числе условий и принципов оплаты труда работников национального объединения саморегулируемых организаций оценщиков;\nиные полномочия, предусмотренные настоящим Федеральным законом и уставными документами национального объединения саморегулируемых организаций оценщиков.\nВ состав коллегиального органа управления национального объединения саморегулируемых организаций оценщиков в обязательном порядке входит по одному представителю от каждого члена национального объединения саморегулируемых организаций оценщиков.\nНе менее чем двадцать пять процентов состава коллегиального органа управления национального объединения саморегулируемых организаций оценщиков должны составлять независимые эксперты, потребители услуг в области оценочной деятельности, представители научной и педагогической общественности и иные не являющиеся членами или представителями членов саморегулируемых организаций оценщиков лица.\nСостав коллегиального органа управления национального объединения саморегулируемых организаций оценщиков подлежит ротации один раз в два года в порядке, установленном учредительными документами национального объединения саморегулируемых организаций оценщиков.\nКоллегиальный орган управления национального объединения саморегулируемых организаций оценщиков возглавляется председателем, который избирается решением общего собрания членов национального объединения саморегулируемых организаций оценщиков сроком на один год.\nПредседателем коллегиального органа управления национального объединения саморегулируемых организаций оценщиков не могут быть представители федеральных органов государственной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления. Одно и то же лицо не может занимать должность председателя коллегиального органа управления национального объединения саморегулируемых организаций оценщиков более двух раз подряд.\nПредседатель коллегиального органа управления национального объединения саморегулируемых организаций оценщиков организует работу коллегиального органа управления национального объединения саморегулируемых организаций оценщиков и председательствует на заседаниях коллегиального органа управления национального объединения саморегулируемых организаций оценщиков.\nЗаседания коллегиального органа управления национального объединения саморегулируемых организаций оценщиков созываются председателем коллегиального органа управления национального объединения саморегулируемых организаций оценщиков. Заседания коллегиального органа управления национального объединения саморегулируемых организаций оценщиков могут быть созваны по инициативе не менее одной трети членов коллегиального органа управления национального объединения саморегулируемых организаций оценщиков. Решение коллегиального органа управления национального объединения саморегулируемых организаций оценщиков считается принятым, если за него проголосовали не менее чем две трети участников заседания и при этом в заседании участвовали не менее чем пятьдесят процентов общего числа членов коллегиального органа управления национального объединения саморегулируемых организаций оценщиков.\nКаждый член коллегиального органа управления национального объединения саморегулируемых организаций оценщиков имеет один голос. В случае равенства голосов при принятии решений этим органом управления голос председателя коллегиального органа управления национального объединения саморегулируемых организаций оценщиков является решающим.\nИсполнительный орган национального объединения саморегулируемых организаций оценщиков избирается на срок до двух лет общим собранием членов национального объединения саморегулируемых организаций оценщиков. Размеры вознаграждений и компенсаций лицам, входящим в состав исполнительного органа национального объединения саморегулируемых организаций оценщиков, устанавливаются решением общего собрания членов национального объединения саморегулируемых организаций оценщиков.\nЛица, входящие в состав исполнительного органа национального объединения саморегулируемых организаций оценщиков, не вправе:\nбыть избранными в состав коллегиального органа управления национального объединения саморегулируемых организаций оценщиков;\nприобретать ценные бумаги, эмитентами которых или должниками по которым являются участники национального объединения саморегулируемых организаций оценщиков и их члены, их дочерние и зависимые общества;\nзаключать с участниками национального объединения саморегулируемых организаций оценщиков и их членами любые договоры имущественного страхования, кредитные договоры, соглашения о поручительстве;\nосуществлять оценочную деятельность;\nучреждать юридические лица, осуществляющие оценочную деятельность, становиться участниками таких юридических лиц;\nявляться членами органов управления участников национального объединения саморегулируемых организаций оценщиков и юридических лиц, осуществляющих оценочную деятельность, работниками, состоящими в штате указанных организаций.\nНациональное объединение саморегулируемых организаций оценщиков обязано иметь в информационно-телекоммуникационной сети \"Интернет\" официальный сайт, в электронный адрес которого включено доменное имя, права на которое принадлежат национальному объединению саморегулируемых организаций оценщиков (далее - официальный сайт национального объединения саморегулируемых организаций оценщиков).\nНациональное объединение саморегулируемых организаций оценщиков обязано разместить на официальном сайте национального объединения саморегулируемых организаций оценщиков:\nполное и (в случае, если имеется) сокращенное наименование, место нахождения, номера контактных телефонов и адрес электронной почты, полные и (в случае, если имеются) сокращенные наименования некоммерческих организаций, членом которых является национальное объединение саморегулируемых организаций оценщиков, места их нахождения, номера контактных телефонов и адреса электронной почты;\nгосударственный регистрационный номер, присвоенный при государственной регистрации юридического лица, зарегистрированного в качестве национального объединения саморегулируемых организаций оценщиков, идентификационный номер налогоплательщика;\nсостав членов национального объединения саморегулируемых организаций оценщиков;\nуведомление о созыве общего собрания членов национального объединения саморегулируемых организаций оценщиков с указанием даты, места и времени его проведения не позднее чем за десять рабочих дней до даты его проведения;\nпротоколы заседаний органов управления, рабочих групп и иных структурных подразделений национального объединения саморегулируемых организаций оценщиков, их аудио- и видеозаписи, приказы и распоряжения исполнительного директора национального объединения саморегулируемых организаций оценщиков;\nгодовую бухгалтерскую (финансовую) отчетность национального объединения саморегулируемых организаций оценщиков и аудиторское заключение в отношении указанной отчетности;\nсмету доходов и расходов национального объединения саморегулируемых организаций оценщиков;\nучредительные документы национального объединения саморегулируемых организаций оценщиков;\nинформацию о структуре, компетенции, персональном составе коллегиального органа управления, единоличного исполнительного органа управления, комитетов, комиссий, рабочих групп и иных структурных подразделений национального объединения саморегулируемых организаций оценщиков;\nинформацию о третейских судах, созданных при национальном объединении саморегулируемых организаций оценщиков;\nинформацию об участии национального объединения саморегулируемых организаций оценщиков в судебных процессах с указанием номеров дел, наименований судов, предметов исков, решений судов;\nинформацию о ходе и результатах предварительной экспертизы нормативных правовых актов и рассмотрения проектов нормативных правовых актов, в проведении которых национальное объединение саморегулируемых организаций оценщиков принимало участие;\nинформацию о выставках, семинарах, конференциях, совещаниях и других мероприятиях, проводимых национальным объединением саморегулируемых организаций оценщиков;\nинформацию о взаимодействии с органами государственной власти и органами местного самоуправления по вопросам, связанным с деятельностью национального объединения саморегулируемых организаций оценщиков (официальные письма, обращения, мероприятия);\nиную информацию, размещение которой на официальном сайте национального объединения саморегулируемых организаций оценщиков предусмотрено его внутренними документами.\nНациональное объединение саморегулируемых организаций оценщиков обязано разместить на официальном сайте национального объединения саморегулируемых организаций оценщиков все изменения, внесенные в документы, или изменение информации, определенной частью двадцать третьей настоящей статьи, не позднее дня, следующего за днем, когда такие изменения были приняты, произошли либо стали известны национальному объединению саморегулируемых организаций оценщиков, если иной срок не предусмотрен уставом национального объединения саморегулируемых организаций оценщиков.\nНациональное объединение саморегулируемых организаций оценщиков в случае возникновения его несоответствия требованиям части второй настоящей статьи обязано обратиться в уполномоченный федеральный орган исполнительной власти, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, с заявлением о несоответствии национального объединения саморегулируемых организаций оценщиков требованиям части второй настоящей статьи и прекращении регистрации в качестве национального объединения саморегулируемых организаций оценщиков (далее - заявление о прекращении регистрации) не позднее чем в течение трех дней с даты возникновения такого несоответствия.\nПри поступлении от национального объединения саморегулируемых организаций оценщиков заявления о прекращении регистрации или при выявлении уполномоченным федеральным органом исполнительной власти, осуществляющим функции по надзору за деятельностью саморегулируемых организаций оценщиков, несоответствия национального объединения саморегулируемых организаций оценщиков требованиям части второй настоящей статьи указанный федеральный орган прекращает регистрацию национального объединения саморегулируемых организаций оценщиков, о чем вносит соответствующие сведения в единый государственный реестр саморегулируемых организаций оценщиков в срок, не превышающий пяти рабочих дней с даты поступления заявления о прекращении регистрации или выявления этого несоответствия.\nВ случае прекращения регистрации некоммерческой организации в качестве национального объединения саморегулируемых организаций оценщиков имущество, составляющее компенсационный фонд саморегулируемой организации оценщиков и переданное национальному объединению саморегулируемых организаций оценщиков в соответствии с частью девятой статьи 24.8 настоящего Федерального закона, подлежит внесению в депозит нотариуса.\nНекоммерческая организация, не зарегистрированная в качестве национального объединения саморегулируемых организаций оценщиков, не вправе использовать в своем наименовании слова \"национальное объединение саморегулируемых организаций оценщиков\".\nСаморегулируемые организации оценщиков вправе образовывать иные объединения саморегулируемых организаций в соответствии с законодательством Российской Федерации о некоммерческих организациях.\nНекоммерческая организация вместе с документами, указанными в части пятой настоящей статьи, вправе по собственной инициативе представить в уполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, копии учредительных документов. (Дополнение частью - Федеральный закон от 31.07.2025 № 304-ФЗ)\nУполномоченный федеральный орган, осуществляющий функции по надзору за деятельностью саморегулируемых организаций оценщиков, при рассмотрении заявления о включении некоммерческой организации в единый государственный реестр саморегулируемых организаций оценщиков в качестве национального объединения саморегулируемых организаций оценщиков запрашивает копии учредительных документов такой некоммерческой организации в федеральном органе исполнительной власти, осуществляющем государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств. (Дополнение частью - Федеральный закон от 31.07.2025 № 304-ФЗ)\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 157-ФЗ) (В редакции Федерального закона от 21.07.2014 № 225-ФЗ)"],
["24.11","Понятие государственной кадастровой оценки","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-06-02","Статья 24.11. Понятие государственной кадастровой оценки\nДля целей настоящего Федерального закона под государственной кадастровой оценкой понимается совокупность действий, включающих в себя:\nпринятие решения о проведении государственной кадастровой оценки;\nформирование перечня объектов недвижимости, подлежащих государственной кадастровой оценке;\nотбор исполнителя работ по определению кадастровой стоимости (далее - исполнитель работ) и заключение с ним договора на проведение оценки;\nопределение кадастровой стоимости и составление отчета об определении кадастровой стоимости;\nабзац; (Утратил силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nутверждение результатов определения кадастровой стоимости;\nвнесение результатов определения кадастровой стоимости в государственный кадастр недвижимости.\nРассмотрение споров о результатах определения кадастровой стоимости осуществляется с учетом особенностей, установленных настоящим Федеральным законом."],
["24.12","Принятие решения о проведении государственной кадастровой оценки","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-07-03","Статья 24.12. Принятие решения о проведении государственной кадастровой оценки\nГосударственная кадастровая оценка проводится по решению исполнительного органа государственной власти субъекта Российской Федерации или в случаях, установленных законодательством субъекта Российской Федерации, по решению органа местного самоуправления не чаще чем один раз в течение трех лет (в городах федерального значения не чаще чем один раз в течение двух лет) с даты, по состоянию на которую была проведена государственная кадастровая оценка (далее - дата проведения последней государственной кадастровой оценки). (В редакции Федерального закона от 03.07.2016 № 360-ФЗ)\nОрган, принявший решение о проведении государственной кадастровой оценки, является заказчиком работ по определению кадастровой стоимости (далее - заказчик работ).\nРешение о проведении государственной кадастровой оценки в обязательном порядке должно содержать следующие сведения:\nгод начала проведения работ по определению кадастровой стоимости;\nвид или виды объектов недвижимости, в отношении которых принято решение о проведении государственной кадастровой оценки;\nкатегория или категории земель в случае, если объектами недвижимости, подлежащими государственной кадастровой оценке, являются земельные участки;\nнаименование субъекта Российской Федерации, на территории которого расположены объекты недвижимости, в отношении которых принято решение о проведении государственной кадастровой оценки;\nнаименования муниципального образования, муниципальных образований, на территориях которых расположены объекты недвижимости и в отношении которых принято решение о проведении государственной кадастровой оценки в случае, если государственной кадастровой оценке подлежат объекты недвижимости, расположенные на территориях не всех муниципальных образований, входящих в состав субъекта Российской Федерации.\nОрган, принявший решение о проведении государственной кадастровой оценки, в срок, не превышающий десяти рабочих дней с даты принятия такого решения, размещает его на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" (в случае отсутствия такого сайта у органа, принявшего решение о проведении государственной кадастровой оценки, - на официальном сайте соответствующего субъекта Российской Федерации в информационно-телекоммуникационной сети \"Интернет\") и направляет его копию в уполномоченный Правительством Российской Федерации федеральный орган исполнительной власти, осуществляющий функции по государственной кадастровой оценке (далее - орган, осуществляющий функции по государственной кадастровой оценке).\n(Приостановлено действие статьи 24.12 - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["24.13","Формирование перечня объектов недвижимости, подлежащих государственной кадастровой оценке","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-07-03","Статья 24.13. Формирование перечня объектов недвижимости, подлежащих государственной кадастровой оценке\nГосударственная кадастровая оценка проводится в отношении объектов недвижимости, учтенных в государственном кадастре недвижимости.\nПеречень объектов недвижимости, подлежащих государственной кадастровой оценке (далее - перечень), формируется и предоставляется заказчику работ по его запросу органом, осуществляющим функции по государственной кадастровой оценке, в порядке и в соответствии с требованиями к содержанию запроса, которые установлены уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nПри формировании перечня указываются количественные и качественные характеристики объектов недвижимости, необходимые для проведения государственной кадастровой оценки и содержащиеся в государственном кадастре недвижимости.\nПредусмотренные настоящей статьей полномочия по формированию и предоставлению перечня органа, осуществляющего функции по государственной кадастровой оценке, на основании решения данного органа вправе осуществлять подведомственные ему государственные бюджетные учреждения.\n(Приостановлено действие статьи 24.13 - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["24.14","Отбор исполнителя работ и заключение с ним договора на проведение оценки","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-07-03","Статья 24.14. Отбор исполнителя работ и заключение с ним договора на проведение оценки\nДля проведения работ по определению кадастровой стоимости привлекаются на конкурсной основе лица, имеющие право на заключение договора на проведение оценки, в соответствии с законодательством Российской Федерации о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд с учетом особенностей, установленных настоящим Федеральным законом.\nОсуществление деятельности по определению кадастровой стоимости допускается при наличии у исполнителя работ договора страхования ответственности за причинение вреда имуществу в результате осуществления указанной деятельности.\nДополнительные требования к исполнителю работ устанавливаются Правительством Российской Федерации.\nДоговор страхования ответственности за причинение вреда имуществу третьих лиц в результате осуществления деятельности по определению кадастровой стоимости заключается на страховую сумму в размере не менее чем тридцать миллионов рублей на срок не менее чем три года.\nЗаказчик работ в срок не более чем пять рабочих дней со дня заключения договора на проведение работ по определению кадастровой стоимости направляет в орган, осуществляющий функции по государственной кадастровой оценке, следующие сведения:\nо месте нахождения заказчика работ;\nоб организационно-правовой форме исполнителя работ, о его полном наименовании и месте нахождения;\nо дате или сроке сдачи результатов работ по договору на проведение работ по определению кадастровой стоимости.\n(Приостановлено действие статьи 24.14 - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["24.15","Определение кадастровой стоимости и составление отчета об определении кадастровой стоимости","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-07-03","Статья 24.15. Определение кадастровой стоимости и составление отчета об определении кадастровой стоимости\nОпределение кадастровой стоимости осуществляется оценщиками в соответствии с требованиями настоящего Федерального закона, актов уполномоченного федерального органа, осуществляющего функции по нормативно-правовому регулированию оценочной деятельности, стандартов и правил оценочной деятельности, регулирующих вопросы определения кадастровой стоимости, за исключением случая, установленного статьей 24.19 настоящего Федерального закона.\nДатой определения кадастровой стоимости объектов недвижимости в рамках проведения государственной кадастровой оценки является дата, по состоянию на которую сформирован перечень.\nСоставление отчета об определении кадастровой стоимости осуществляется на бумажном носителе не менее чем в трех экземплярах и на электронном носителе в форме электронного документа.\nТребования к отчету об определении кадастровой стоимости устанавливаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности (далее - требования к отчету).\nВ течение трех рабочих дней с даты составления проекта отчета об определении кадастровой стоимости, составленного в форме электронного документа и соответствующего требованиям к отчету, исполнитель работ направляет такой проект отчета в орган, осуществляющий функции по государственной кадастровой оценке, и в саморегулируемую организацию оценщиков, членами которой являются оценщики, осуществившие определение кадастровой стоимости, о чем извещает заказчика работ.\nВ целях обеспечения возможности ознакомления с проектом отчета об определении кадастровой стоимости и представления замечаний к нему орган, осуществляющий функции по государственной кадастровой оценке, в течение трех рабочих дней с даты получения такого проекта отчета включает его в фонд данных государственной кадастровой оценки, предусмотренный статьей 24.21 настоящего Федерального закона, на двадцать рабочих дней, за исключением случаев, предусмотренных порядком ведения фонда данных государственной кадастровой оценки и предоставления сведений из этого фонда, утвержденным уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nО включении или невозможности включения в фонд данных государственной кадастровой оценки проекта отчета об определении кадастровой стоимости орган, осуществляющий функции по государственной кадастровой оценке, уведомляет заказчика работ и исполнителя работ любым доступным способом (телеграммой, телефонограммой, факсограммой) в течение пяти рабочих дней с даты получения такого проекта отчета. В случае невозможности включения в фонд данных государственной кадастровой оценки проекта отчета об определении кадастровой стоимости орган, осуществляющий функции по государственной кадастровой оценке, в уведомлении указывает причины, по которым включение такого проекта отчета невозможно.\nВ случае получения уведомления о невозможности включения в фонд данных государственной кадастровой оценки проекта отчета об определении кадастровой стоимости исполнитель работ обеспечивает устранение причин, повлекших за собой невозможность размещения такого проекта отчета, и направляет его в орган, осуществляющий функции по государственной кадастровой оценке.\nИнформацию о включении в фонд данных государственной кадастровой оценки проекта отчета об определении кадастровой стоимости заказчик работ размещает на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" (в случае отсутствия этого сайта у заказчика работ - на официальном сайте соответствующего субъекта Российской Федерации в информационно-телекоммуникационной сети \"Интернет\") с указанием адресов, по которым размещаются замечания, представленные к проекту отчета об определении кадастровой стоимости.\nЗамечания к проекту отчета об определении кадастровой стоимости включаются в фонд данных государственной кадастровой оценки любыми заинтересованными лицами в течение двадцати рабочих дней с даты включения такого проекта отчета.\nЗамечания к проекту отчета об определении кадастровой стоимости наряду с изложением их сути в обязательном порядке должны содержать:\nфамилию, имя и (при наличии) отчество - для физического лица, полное наименование - для юридического лица, номер контактного телефона, адрес электронной почты лица, представившего замечания к проекту отчета об определении кадастровой стоимости;\nуказание на номера страниц проекта отчета об определении кадастровой стоимости и (при наличии) приложения, к которым имеются замечания;\nуказание на кадастровый номер и (или) адрес объекта недвижимости в случае, если в отношении определения кадастровой стоимости такого объекта имеется замечание по поводу определения его кадастровой стоимости.\nЗамечания к проекту отчета об определении кадастровой стоимости, не соответствующие требованиям, установленным настоящей статьей, не рассматриваются.\nВ случае внесения исполнителем работ изменений в проект отчета об определении кадастровой стоимости по итогам анализа представленных к такому проекту отчета замечаний изменения подлежат внесению в такой проект отчета в течение срока, когда осуществляется его включение в фонд данных государственной кадастровой оценки, по мере представления замечаний и в течение не более чем пятнадцать рабочих дней с даты истечения указанного срока.\nПо истечении всех указанных сроков исполнитель работ составляет отчет об определении кадастровой стоимости, включающий в себя справку, содержащую информацию о всех представленных к такому проекту отчета замечаниях, как учтенных, так и неучтенных, с их соответствующим обоснованием или об отсутствии замечаний к проекту отчета об определении кадастровой стоимости (далее - справка о замечаниях).\nЧасть. (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Приостановлено действие статьи 24.15 - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["24.16","(Статья утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2016-06-02","Статья 24.16. (Статья утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)"],
["24.17","Утверждение результатов определения кадастровой стоимости","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2023-06-13","Статья 24.17. Утверждение результатов определения кадастровой стоимости\nВ течение двадцати рабочих дней с даты принятия отчета об определении кадастровой стоимости заказчик работ принимает акт об утверждении содержащихся в таком отчете кадастровой стоимости и удельных показателей кадастровой стоимости объектов недвижимости для кадастрового квартала, населенного пункта, муниципального района, муниципального округа, городского округа, субъекта Российской Федерации (далее - акт об утверждении результатов определения кадастровой стоимости), который вступает в силу после даты его официального опубликования (обнародования). (В редакции Федерального закона от 13.06.2023 № 228-ФЗ)\nДатой утверждения результатов определения кадастровой стоимости считается дата вступления в силу акта об утверждении результатов определения кадастровой стоимости и соответствующей нормы такого акта.\nВ течение трех рабочих дней с даты утверждения результатов определения кадастровой стоимости копия акта об утверждении результатов определения кадастровой стоимости (включая сведения о датах его опубликования и вступления в силу), один экземпляр отчета об определении кадастровой стоимости, составленного в форме электронного документа, направляются заказчиком работ в орган, осуществляющий функции по государственной кадастровой оценке. (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\n(Приостановлено действие статьи 24.17 - Федеральный закон от 03.07.2016 № 360-ФЗ)"],
["24.18","Рассмотрение споров о результатах определения кадастровой стоимости","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2022-12-19","Статья 24.18. Рассмотрение споров о результатах определения кадастровой стоимости\nРезультаты определения кадастровой стоимости могут быть оспорены юридическими лицами в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, а также органами государственной власти, органами публичной власти федеральной территории, органами местного самоуправления в отношении объектов недвижимости, находящихся в государственной или муниципальной собственности (за исключением случаев, установленных настоящей статьей), в суде и комиссии по рассмотрению споров о результатах определения кадастровой стоимости (далее - комиссия). (В редакции федеральных законов от 29.07.2017 № 274-ФЗ, от 02.07.2021 № 351-ФЗ)\n(О несоответствии Конституции Российской Федерации части - Постановление Конституционного Суда Российской Федерации от 05.07.2016 № 15-П)\nРезультаты определения кадастровой стоимости могут быть оспорены физическими лицами в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, в суде или комиссии.\nДля оспаривания физическими лицами результатов определения кадастровой стоимости в суде предварительное обращение в комиссию не является обязательным.\nВ случае оспаривания результатов определения кадастровой стоимости рыночная стоимость объекта недвижимости должна быть установлена на дату, по состоянию на которую установлена его кадастровая стоимость. Комиссия создается органом, осуществляющим функции по государственной кадастровой оценке, на территории соответствующего субъекта Российской Федерации.\nВ состав комиссии входят представители органа исполнительной власти субъекта Российской Федерации, органа, осуществляющего функции по государственной кадастровой оценке, федерального органа исполнительной власти, уполномоченного Правительством Российской Федерации на осуществление государственного кадастрового учета, государственной регистрации прав, ведение Единого государственного реестра недвижимости, его территориальных органов (далее - орган регистрации прав) или на основании акта Правительства Российской Федерации публично-правовой компании, созданной в соответствии с Федеральным законом от 30 декабря 2021 года № 448-ФЗ \"О публично-правовой компании \"Роскадастр\" (далее - публично-правовая компания), и подлежащие обязательной ротации не менее чем на семьдесят пять процентов один раз в три года представители предпринимательского сообщества, саморегулируемых организаций оценщиков. (В редакции федеральных законов от 03.07.2016 № 361-ФЗ, от 19.12.2022 № 546-ФЗ)\nТребования к входящим в состав комиссии представителям предпринимательского сообщества, саморегулируемых организаций оценщиков, порядок создания и работы комиссии, включая порядок представления кандидатур для включения в состав комиссии, в том числе в целях ротации (далее - порядок создания и работы комиссии), формы принимаемых комиссией документов устанавливаются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию в области оценочной деятельности.\nПри этом лица, замещающие государственные должности Российской Федерации, государственные должности субъектов Российской Федерации, должности государственной и муниципальной службы, должны составлять не более половины членов состава комиссии.\nКандидатуры представителей предпринимательского сообщества, в том числе в целях ротации, выдвигаются некоммерческими организациями, основанными на членстве и объединяющими потребителей оценочных услуг.\nДля оспаривания результатов определения кадастровой стоимости в комиссии юридические лица, физические лица в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, и органы государственной власти, органы публичной власти федеральной территории, органы местного самоуправления в отношении объектов недвижимости, находящихся в государственной или муниципальной собственности (далее также - заявители), обращаются в комиссию с заявлением о пересмотре результатов определения кадастровой стоимости (далее - заявление о пересмотре кадастровой стоимости). (В редакции Федерального закона от 02.07.2021 № 351-ФЗ)\nЗаявление о пересмотре кадастровой стоимости может быть подано в комиссию в период с даты внесения в Единый государственный реестр недвижимости результатов определения кадастровой стоимости по дату внесения в Единый государственный реестр недвижимости результатов определения кадастровой стоимости, полученных при проведении очередной государственной кадастровой оценки или в соответствии со статьей 24.19 настоящего Федерального закона. (В редакции федеральных законов от 03.07.2016 № 361-ФЗ, от 18.03.2020 № 66-ФЗ)\nОснованием для пересмотра результатов определения кадастровой стоимости является:\nнедостоверность сведений об объекте недвижимости, использованных при определении его кадастровой стоимости;\nустановление в отношении объекта недвижимости его рыночной стоимости на дату, по состоянию на которую установлена его кадастровая стоимость.\nС заявлением о пересмотре кадастровой стоимости на основании недостоверности сведений об объекте недвижимости, использованных при определении его кадастровой стоимости, в комиссию могут обратиться юридические лица, физические лица в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, а также органы государственной власти, органы публичной власти федеральной территории, органы местного самоуправления в отношении объектов недвижимости, расположенных на территории субъекта Российской Федерации, федеральной территории или муниципального образования. (В редакции Федерального закона от 02.07.2021 № 351-ФЗ)\nС заявлением о пересмотре кадастровой стоимости на основании установления в отношении объекта недвижимости его рыночной стоимости на дату, по состоянию на которую была установлена его кадастровая стоимость, в комиссию могут обратиться юридические лица, физические лица в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, а также органы государственной власти, органы публичной власти федеральной территории, органы местного самоуправления, в отношении объектов недвижимости, находящихся в государственной или муниципальной собственности. (В редакции Федерального закона от 02.07.2021 № 351-ФЗ)\nВ целях выявления основания для пересмотра результатов определения кадастровой стоимости объекта недвижимости заявитель вправе обратиться к заказчику работ в случае, если кадастровая стоимость объекта недвижимости определена в ходе проведения государственной кадастровой оценки, или в орган, осуществляющий функции по государственной кадастровой оценке, в случае, если кадастровая стоимость объекта недвижимости определена в соответствии со статьей 24.19 настоящего Федерального закона, с запросом о предоставлении сведений об объекте недвижимости, использованных при определении его кадастровой стоимости.\nВ течение семи рабочих дней с даты поступления указанного запроса заказчик работ и орган, осуществляющий функции по государственной кадастровой оценке, обязаны предоставить заявителю соответствующие сведения.\nК заявлению о пересмотре кадастровой стоимости прилагаются:\nвыписка из Единого государственного реестра недвижимости о кадастровой стоимости объекта недвижимости, содержащая сведения об оспариваемых результатах определения кадастровой стоимости; (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nкопия правоустанавливающего или правоудостоверяющего документа на объект недвижимости в случае, если заявление о пересмотре кадастровой стоимости подается лицом, обладающим правом на объект недвижимости; (В редакции Федерального закона от 18.03.2020 № 66-ФЗ)\nдокументы, подтверждающие недостоверность сведений об объекте недвижимости, использованных при определении его кадастровой стоимости, в случае, если заявление о пересмотре кадастровой стоимости подается на основании недостоверности указанных сведений;\nотчет, составленный на бумажном носителе и в форме электронного документа, в случае, если заявление о пересмотре кадастровой стоимости подается на основании установления в отношении объекта недвижимости его рыночной стоимости;\nабзац; (Утратил силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nЗаявление о пересмотре кадастровой стоимости без приложения указанных документов к рассмотрению не принимается.\nК заявлению о пересмотре кадастровой стоимости также могут прилагаться иные документы.\nЗаявление о пересмотре кадастровой стоимости рассматривается комиссией в течение одного месяца с даты его поступления.\nВ семидневный срок с даты поступления заявления о пересмотре кадастровой стоимости комиссия направляет уведомление о поступлении данного заявления и принятии его к рассмотрению с указанием даты его рассмотрения в орган местного самоуправления, на территории которого расположен объект недвижимости, результаты определения кадастровой стоимости которого оспариваются, и лицу, обладающему правом на такой объект недвижимости.\nДля получения информации, необходимой для работы комиссии, председатель комиссии вправе обратиться с запросом к исполнителю работ по определению кадастровой стоимости, результаты определения которой оспариваются, и (или) к оценщикам, составившим отчет, содержащий результаты определения кадастровой стоимости, которые оспариваются, и (или) к оценщикам, составившим отчет об определении рыночной стоимости объекта недвижимости, кадастровая стоимость которого оспаривается, в случаях и в порядке, которые предусмотрены порядком создания и работы комиссии.\nЕсли основанием подачи заявления о пересмотре кадастровой стоимости была недостоверность сведений об объекте недвижимости, использованных при определении его кадастровой стоимости, по результатам рассмотрения данного заявления комиссия вправе принять одно из следующих решений:\nоб отклонении заявления о пересмотре кадастровой стоимости в случае использования достоверных сведений об объекте недвижимости при определении кадастровой стоимости;\nо пересмотре результатов определения кадастровой стоимости в случае недостоверности сведений об объекте недвижимости, использованных при определении его кадастровой стоимости.\nВ случае принятия решения о пересмотре результатов определения кадастровой стоимости на основании недостоверности сведений об объекте недвижимости, использованных при определении его кадастровой стоимости, заказчик работ обеспечивает определение кадастровой стоимости объекта недвижимости, в отношении которого было принято указанное решение, в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nВ случае, если заявление о пересмотре кадастровой стоимости подано на основании установления в отчете рыночной стоимости объекта недвижимости, комиссия принимает решение об определении кадастровой стоимости объекта недвижимости в размере его рыночной стоимости или отклоняет заявление о пересмотре кадастровой стоимости в случаях, предусмотренных порядком создания и работы комиссии.\nЗаседание комиссии является правомочным, если на нем присутствует не менее половины ее членов. Порядок голосования комиссии устанавливается порядком создания и работы комиссии.\nВ течение пяти рабочих дней с даты принятия по результатам рассмотрения заявления о пересмотре кадастровой стоимости соответствующего решения комиссия уведомляет об этом лицо, обладающее правом на объект недвижимости, результаты определения кадастровой стоимости которого оспариваются, и орган местного самоуправления, на территории которого расположен объект недвижимости.\nРешения комиссии могут быть оспорены в суде.\nРешение комиссии об определении кадастровой стоимости земельного участка в размере его рыночной стоимости может быть оспорено в суде органом местного самоуправления, органом государственной власти города федерального значения Москвы, Санкт-Петербурга или Севастополя в отношении земельного участка, не находящегося в собственности муниципального образования либо города федерального значения Москвы, Санкт-Петербурга или Севастополя, но расположенного на соответствующей территории, в случае, если по заявлению собственника этого земельного участка его кадастровая стоимость была существенно снижена на основании установления рыночной стоимости, чем могут быть затронуты права и законные интересы данного муниципального образования либо города федерального значения Москвы, Санкт-Петербурга или Севастополя, в том числе связанные с поступлениями налоговых доходов в местный бюджет или бюджет города федерального значения Москвы, Санкт-Петербурга или Севастополя. (Дополнение частью - Федеральный закон от 29.07.2017 № 274-ФЗ)\nРезультаты определения кадастровой стоимости могут быть оспорены юридическими лицами в случае, если результаты определения кадастровой стоимости затрагивают права и обязанности этих лиц, а также органами государственной власти, органами местного самоуправления в отношении объекта недвижимости, находящегося в государственной или муниципальной собственности, в суде по основаниям недостоверности сведений об объекте недвижимости, использованных при определении его кадастровой стоимости или установлении в отношении объекта недвижимости его рыночной стоимости на дату, по состоянию на которую установлена его кадастровая стоимость, только в случае отклонения комиссией заявления о пересмотре кадастровой стоимости, поданного по соответствующему основанию, либо в случае, если заявление о пересмотре кадастровой стоимости не рассмотрено комиссией в установленный настоящей статьей срок.\nВ случае оспаривания результатов определения кадастровой стоимости в суде по основаниям для их пересмотра, предусмотренным частью одиннадцатой настоящей статьи, решение комиссии не является предметом рассмотрения при рассмотрении требований заявителя. (В редакции Федерального закона от 29.07.2017 № 274-ФЗ)\nВ случае принятия комиссией решения о пересмотре результатов определения кадастровой стоимости в течение пяти рабочих дней с даты его принятия комиссия направляет в орган, осуществляющий функции по государственной кадастровой оценке, и орган регистрации прав копию указанного решения. В случае принятия комиссией решения о пересмотре результатов определения кадастровой стоимости на основании определения в отношении объекта недвижимости его рыночной стоимости комиссия в течение пяти рабочих дней с даты принятия такого решения также направляет: (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nотчет об оценке рыночной стоимости объекта недвижимости, который составлен в форме электронного документа и на основании которого оспорена кадастровая стоимость, в орган, осуществляющий функции по государственной кадастровой оценке; (В редакции Федерального закона от 02.06.2016 № 172-ФЗ)\nсведения о кадастровой стоимости в орган регистрации прав. (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 08.06.2015 № 145-ФЗ) (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 08.06.2015 № 145-ФЗ) (Утратила силу - Федеральный закон от 02.06.2016 № 172-ФЗ)\n(Особенности применения статьи 24.18 - Федеральный закон от 21.07.2014 № 225-ФЗ)"],
["24.19","Определение кадастровой стоимости вновь учтенных объектов недвижимости, ранее учтенных объектов недвижимости при включении сведений о них в Единый государственный реестр недвижимости и объектов недвижимости, в отношении которых произошло изменение их количественных и (или) качественных характеристик","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2022-12-19","Статья 24.19. Определение кадастровой стоимости вновь учтенных объектов недвижимости, ранее учтенных объектов недвижимости при включении сведений о них в Единый государственный реестр недвижимости и объектов недвижимости, в отношении которых произошло изменение их количественных и (или) качественных характеристик\n(Наименование в редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nПри осуществлении государственного кадастрового учета ранее не учтенных объектов недвижимости, включения в Единый государственный реестр недвижимости сведений о ранее учтенном объекте недвижимости или внесения в Единый государственный реестр недвижимости соответствующих сведений при изменении качественных и (или) количественных характеристик объектов недвижимости, влекущем за собой изменение их кадастровой стоимости, орган, осуществляющий функции по государственной кадастровой оценке, осуществляет определение кадастровой стоимости объектов недвижимости в порядке, установленном уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности. (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nДатой определения кадастровой стоимости объекта недвижимости в случаях, предусмотренных настоящей статьей, является дата внесения сведений о нем в Единый государственный реестр недвижимости, повлекшего за собой необходимость определения кадастровой стоимости в соответствии с настоящей статьей. (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nПредусмотренные настоящей статьей полномочия по определению кадастровой стоимости вновь учтенных объектов недвижимости, ранее учтенных объектов недвижимости при включении сведений о них в Единый государственный реестр недвижимости и объектов недвижимости, в отношении которых произошло изменение их количественных и (или) качественных характеристик, органа, осуществляющего функции по государственной кадастровой оценке, осуществляет публично-правовая компания. (В редакции федеральных законов от 03.07.2016 № 361-ФЗ, от 19.12.2022 № 546-ФЗ)"],
["24.20","Внесение результатов определения кадастровой стоимости в Единый государственный реестр недвижимости","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","2020-07-31","Статья 24.20. Внесение результатов определения кадастровой стоимости в Единый государственный реестр недвижимости\n(Наименование в редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 31.07.2020 № 269-ФЗ)\nВ течение десяти рабочих дней с даты получения сведений о кадастровой стоимости орган регистрации прав осуществляет их внесение в Единый государственный реестр недвижимости, если иное не предусмотрено законодательством Российской Федерации. (В редакции Федерального закона от 03.07.2016 № 361-ФЗ)\nДля целей, предусмотренных законодательством Российской Федерации, применяется кадастровая стоимость, сведения о которой внесены в Единый государственный реестр недвижимости. (В редакции Федерального закона от 31.07.2020 № 269-ФЗ)\nКадастровая стоимость объекта недвижимости применяется для целей, предусмотренных законодательством Российской Федерации, со дня внесения сведений о ней в Единый государственный реестр недвижимости, за исключением случаев, установленных настоящей статьей. (В редакции Федерального закона от 31.07.2020 № 269-ФЗ)\nКадастровая стоимость объекта недвижимости применяется для целей, предусмотренных законодательством Российской Федерации, со дня начала применения кадастровой стоимости, изменяемой вследствие:\nисправления технической ошибки в сведениях Единого государственного реестра недвижимости, послужившего основанием для такого изменения;\nвнесения изменений в акт об утверждении результатов определения кадастровой стоимости, изменяющий кадастровую стоимость объекта недвижимости в сторону уменьшения;\nустановления кадастровой стоимости в результате рассмотрения споров о результатах определения кадастровой стоимости объекта недвижимости.\n(Часть в редакции Федерального закона от 31.07.2020 № 269-ФЗ)\nВ случае наличия нескольких применяемых в один момент времени кадастровых стоимостей, определенных на одну дату, применяется наименьшая из таких стоимостей. (В редакции Федерального закона от 31.07.2020 № 269-ФЗ)\n(Особенности применения статьи 24.20 - Федеральный закон от 21.07.2014 № 225-ФЗ)"],
["24.21","Фонд данных государственной кадастровой оценки","ГЛАВА III.1. ГОСУДАРСТВЕННАЯ КАДАСТРОВАЯ ОЦЕНКА","","Статья 24.21. Фонд данных государственной кадастровой оценки\nВедение фонда данных государственной кадастровой оценки осуществляется органом, осуществляющим функции по государственной кадастровой оценке.\nОрган, осуществляющий функции по государственной кадастровой оценке, обеспечивает включение в фонд данных государственной кадастровой оценки сведений и материалов, поступающих в такой орган в соответствии со статьями 24.12 - 24.18 настоящего Федерального закона, в течение пяти рабочих дней с даты их поступления, если иное не предусмотрено настоящим Федеральным законом.\nВ рамках ведения фонда данных государственной кадастровой оценки орган, осуществляющий функции по государственной кадастровой оценке, проводит анализ соответствия отчета требованиям к отчету в части, определенной порядком ведения фонда данных государственной кадастровой оценки и предоставления сведений из этого фонда.\nВ целях ведения фонда данных государственной кадастровой оценки орган, осуществляющий функции по государственной кадастровой оценке, также обеспечивает проведение мониторинга рынка недвижимости.\nВ фонд данных государственной кадастровой оценки также включаются иные сведения о кадастровой стоимости, о порядке и об основаниях ее определения, перечень которых, а также требования по их включению в фонд данных государственной кадастровой оценки определяются уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности.\nПорядок ведения фонда данных государственной кадастровой оценки и предоставления сведений из этого фонда устанавливается уполномоченным федеральным органом, осуществляющим функции по нормативно-правовому регулированию оценочной деятельности."],
["25","Вступление в силу настоящего Федерального закона","ГЛАВА IV. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","","Статья 25. Вступление в силу настоящего Федерального закона\nНастоящий Федеральный закон вступает в силу со дня его официального опубликования.\nДокументы об образовании, подтверждающие получение профессиональных знаний в области оценочной деятельности, выданные до вступления в силу настоящего Федерального закона, подлежат приведению в соответствие с нормами настоящего Федерального закона не позднее 1 июля 2000 года."],
["26","Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом","ГЛАВА IV. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","","Статья 26. Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом\nПредложить Президенту Российской Федерации и поручить Правительству Российской Федерации привести свои нормативные правовые акты в соответствие с настоящим Федеральным законом.\nПрезидент Российской Федерации Б.Ельцин\nМосква, Кремль 29 июля 1998 года № 135-ФЗ"]
];
